function solicitarExclusaoConta() {
  if (!confirm("Solicitar exclusão desta conta? A exclusão permanente será agendada para 15 dias.")) return;
  return solicitarCodigoSegurancaConta("request_account_deletion", "confirm_account_deletion", "Confirmar exclusão da conta");
}

function cancelarExclusaoConta() {
  return solicitarCodigoSegurancaConta("request_cancel_deletion", "confirm_cancel_deletion", "Cancelar exclusão da conta");
}

async function exportarDadosContaSeguro() {
  try {
    const data = await accountSecurityRequest("export_account_data");
    const url = URL.createObjectURL(new Blob([JSON.stringify(data, null, 2)], { type: "application/json" }));
    const link = document.createElement("a");
    link.href = url;
    link.download = `simplifica-conta-${hojeIsoData()}.json`;
    link.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    mostrarToast("Dados da conta exportados.", "sucesso");
  } catch (erro) {
    mostrarToast(mensagemErroSegurancaConta(erro?.message), "erro", 6000);
  }
}

function renderSegurancaContaOnline() {
  if (accountSecurityState.loading && !accountSecurityState.loaded) return `<p class="muted">Carregando segurança da conta...</p>`;
  if (accountSecurityState.error && !accountSecurityState.loaded) return `<p class="feedback-status error">${escaparHtml(accountSecurityState.error)}</p>`;
  const settings = accountSecurityState.settings || {};
  const twoFactor = settings.two_factor_enabled === true;
  const deletion = accountSecurityState.deletion;
  const owner = accountSecurityState.role === "owner";
  const events = (accountSecurityState.events || []).slice(0, 8);
  return `
    <div class="security-online-grid">
      <section class="ui3-security-card">
        <div class="security-card-heading"><span class="security-card-icon">${renderUiIcon("seguranca")}</span><div><h3>Autenticação em dois fatores</h3><small>Canal: E-mail</small></div><span class="status-badge ${twoFactor ? "badge-ativo" : ""}">${twoFactor ? "Ativado" : "Desativado"}</span></div>
        <div class="actions">${twoFactor ? `<button class="btn ghost" type="button" onclick="solicitarDesativacao2FAEmail()">Desativar 2FA</button>` : `<button class="btn" type="button" onclick="solicitarAtivacao2FAEmail()">Ativar 2FA por e-mail</button>`}</div>
      </section>
      <section class="ui3-security-card">
        <div class="security-card-heading"><span class="security-card-icon">${renderUiIcon("conta")}</span><div><h3>Login com Google</h3><small>Conectado pelo Supabase Auth</small></div><span class="status-badge badge-ativo">Disponível</span></div>
      </section>
      <section class="ui3-security-card">
        <div class="security-card-heading"><span class="security-card-icon">${renderUiIcon("backup")}</span><div><h3>Exportar dados</h3><small>Gera uma cópia dos dados da conta.</small></div></div>
        <div class="actions"><button class="btn secondary" type="button" onclick="exportarDadosContaSeguro()">Exportar dados</button></div>
      </section>
      ${owner ? `<section class="ui3-security-card ui3-danger-zone account-danger-zone">
        <div class="security-card-heading"><span class="security-card-icon">${renderUiIcon("trash")}</span><div><h3>Zona de perigo</h3><small>Exclusão com prazo de arrependimento de 15 dias.</small></div></div>
        ${deletion?.status === "confirmed"
          ? `<p>Exclusão agendada para <strong>${escaparHtml(new Date(deletion.scheduled_delete_at).toLocaleDateString("pt-BR"))}</strong>.</p><div class="actions"><button class="btn secondary" type="button" onclick="cancelarExclusaoConta()">Cancelar exclusão</button></div>`
          : `<div class="actions"><button class="btn danger" type="button" onclick="solicitarExclusaoConta()">Solicitar exclusão da conta</button></div>`}
      </section>` : ""}
    </div>
    <section class="ui3-security-card"><h3>Histórico de segurança</h3><div class="history-list">${events.length ? events.map((item) => `<div class="history-item"><strong>${escaparHtml(item.message || item.event_type)}</strong><span>${escaparHtml(formatarDataHora(item.created_at))}</span></div>`).join("") : `<p class="empty">Nenhum evento registrado.</p>`}</div></section>`;
}

function contaPendenteExclusao() {
  return accountSecurityState.company?.deletion_status === "pending_deletion" || accountSecurityState.deletion?.status === "confirmed";
}

function renderAccountDeletionBanner() {
  if (!contaPendenteExclusao()) return "";
  const date = accountSecurityState.deletion?.scheduled_delete_at || accountSecurityState.company?.deletion_scheduled_at;
  return `<div class="account-deletion-banner" role="status"><strong>Conta marcada para exclusão${date ? ` em ${escaparHtml(new Date(date).toLocaleDateString("pt-BR"))}` : ""}.</strong><button class="btn secondary" type="button" onclick="cancelarExclusaoConta()">Cancelar exclusão</button></div>`;
}

function isMobile() {
  return window.innerWidth < 768;
}

function isTablet() {
  return window.innerWidth >= 768 && window.innerWidth < 1024;
}

function isDesktop() {
  return window.innerWidth >= 1024;
}

function getViewportMode() {
  const viewportWidth = window.innerWidth || 1024;
  if (viewportWidth < 768) return "mobile";
  if (viewportWidth < 1024) return "tablet";
  return "desktop";
}

function applyViewportModeClasses(target = document.body) {
  if (!target?.classList) return getViewportMode();
  const mode = getViewportMode();
  target.classList.remove("viewport-mobile", "viewport-tablet", "viewport-desktop");
  target.classList.add(`viewport-${mode}`);
  target.dataset.viewportMode = mode;
  return mode;
}

function getUiProfile() {
  return isAndroidNativeApp() ? "android_apk" : "web_pwa";
}

function isWebPwaProfile() {
  return getUiProfile() === "web_pwa";
}

function isPwaSettingsSplitPane(elemento = null) {
  return isWebPwaProfile()
    && !isMobile()
    && !!elemento?.closest?.(".settings-accordion-list");
}

function detectarTipoDispositivo() {
  const agente = navigator.userAgent || "";
  if (/Android|iPhone|iPad|iPod|Mobile/i.test(agente) || isMobile()) return "mobile";
  return "desktop";
}

function nomeTipoDispositivo(tipo) {
  return tipo === "mobile" ? "celular Android" : "Windows/navegador";
}

function getPlatformAdapter() {
  const capacitor = window.Capacitor || null;
  const platform = String(capacitor?.getPlatform?.() || (isAndroid() ? "android-web" : "web")).toLowerCase();
  const isAPK = isAndroidNativeApp();
  const isPWA = !isAPK;
  return {
    id: isAPK ? "android_apk" : "web_pwa",
    platform,
    isPWA,
    isAndroid: isAndroid(),
    isAPK,
    supportsLocalAI: isAPK && !!window.Capacitor?.Plugins?.SimplificaFiles,
    supportsInstallPrompt: isPWA,
    supportsServiceWorker: isPWA && "serviceWorker" in navigator && location.protocol !== "file:",
    safeAreaInsets: {
      top: "env(safe-area-inset-top)",
      right: "env(safe-area-inset-right)",
      bottom: "env(safe-area-inset-bottom)",
      left: "env(safe-area-inset-left)"
    }
  };
}

function getManagedSafeAreaInsets() {
  const safeArea = window.safeArea && typeof window.safeArea === "object" ? window.safeArea : null;
  if (!safeArea) return null;
  const px = (value) => `${Math.max(0, Math.round(Number(value) || 0))}px`;
  return {
    top: px(safeArea.top),
    right: px(safeArea.right),
    bottom: px(safeArea.bottom),
    left: px(safeArea.left),
    keyboard: px(safeArea.keyboardHeight),
    viewportHeight: px(safeArea.viewportHeight || safeArea.visualViewportHeight || window.innerHeight)
  };
}

function getLimitesDispositivos() {
  const limitePlano = getSessionLimitPlano();
  return {
    mobile: limitePlano,
    desktop: limitePlano,
    total: limitePlano
  };
}

function normalizarDispositivosLicenca(lista = billingConfig.registeredDevices) {
  const vistos = new Set();
  return (Array.isArray(lista) ? lista : []).map((item) => {
    const email = normalizarEmail(item?.email);
    const id = String(item?.id || "").trim();
    const tipo = item?.tipo === "desktop" ? "desktop" : "mobile";
    if (!email || !id) return null;
    const chave = `${email}:${tipo}:${id}`;
    if (vistos.has(chave)) return null;
    vistos.add(chave);
    return {
      id,
      email,
      tipo,
      nome: String(item?.nome || nomeTipoDispositivo(tipo)).trim(),
      ultimoAcesso: item?.ultimoAcesso || new Date().toISOString()
    };
  }).filter(Boolean);
}

function getEmailLicencaAtual() {
  const usuario = getUsuarioAtual();
  return normalizarEmail(usuario?.email || billingConfig.licenseEmail || "");
}

function getDataOwnerId() {
  const remoto = getEscopoDadosAtual();
  if (remoto) return remoto;
  const usuario = getUsuarioAtual();
  return isSuperAdmin(usuario) ? "superadmin" : normalizarEmail(usuario?.email || billingConfig.licenseEmail || deviceId);
}

function prepararRegistroOnline(registro = {}) {
  const atualizadoEm = registro.updated_at || registro.updatedAt || registro.atualizadoEm || new Date().toISOString();
  const ownerId = getDataOwnerId();
  return {
    ...registro,
    user_id: pareceUuid(ownerId) ? ownerId : registro.user_id || registro.userId || null,
    owner_id: ownerId,
    source_device_id: registro.source_device_id || registro.sourceDeviceId || deviceId,
    sourceDeviceId: registro.sourceDeviceId || registro.source_device_id || deviceId,
    sync_status: registro.sync_status || registro.syncStatus || "pending",
    updated_at: atualizadoEm,
    updatedAt: registro.updatedAt || atualizadoEm
  };
}

function gerarUuidOperacional() {
  try {
    if (crypto?.randomUUID) return crypto.randomUUID();
  } catch (_) {}
  return "op-" + Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 10);
}

function gerarHashOperacional(valor = "") {
  const texto = String(valor || "");
  let hash = 2166136261;
  for (let i = 0; i < texto.length; i += 1) {
    hash ^= texto.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).padStart(8, "0");
}

function getPlataformaDispositivoOperacional() {
  const ua = String(navigator?.userAgent || "").toLowerCase();
  if (/android/.test(ua)) return "android";
  if (/iphone|ipad|ipod/.test(ua)) return "ios";
  if (/mobile/.test(ua)) return "mobile-web";
  return "web";
}

function criarMetadadosOperacaoFinanceira(tipo, referencia = {}, opcoes = {}) {
  const agora = opcoes.createdAt || new Date().toISOString();
  const escopo = getEscopoDadosAtual?.() || getDataOwnerId() || "local";
  const referenciaId = referencia.id || referencia.sale_id || referencia.pedidoId || referencia.record_id || Date.now();
  const operationUuid = opcoes.operation_uuid || gerarUuidOperacional();
  const baseRequest = [
    tipo || "financial",
    escopo,
    deviceId,
    referenciaId,
    referencia.total ?? referencia.valor ?? "",
    referencia.status ?? "",
    referencia.updated_at || referencia.atualizadoEm || agora
  ].join("|");
  const clientRequestId = opcoes.client_request_id || `${tipo || "financial"}:${escopo}:${deviceId}:${referenciaId}:${gerarHashOperacional(baseRequest)}`;
  const requestHash = opcoes.request_hash || gerarHashOperacional(JSON.stringify({
    tipo,
    referenciaId,
    total: referencia.total ?? referencia.valor ?? null,
    itens: referencia.itens?.length ?? null,
    status: referencia.status || "",
    cliente: referencia.cliente || ""
  }));
  const offline = !estaOnline();
  return {
    operation_uuid: operationUuid,
    operationUuid,
    client_request_id: clientRequestId,
    clientRequestId,
    request_hash: requestHash,
    requestHash,
    created_from_device: deviceId,
    createdFromDevice: deviceId,
    financial_flow_version: FINANCIAL_FLOW_VERSION,
    financialFlowVersion: FINANCIAL_FLOW_VERSION,
    operation_source: opcoes.operation_source || "pwa_shadow",
    operationSource: opcoes.operation_source || "pwa_shadow",
    sync_version: FINANCIAL_SYNC_VERSION,
    syncVersion: FINANCIAL_SYNC_VERSION,
    sync_attempts: opcoes.sync_attempts ?? 0,
    syncAttempts: opcoes.sync_attempts ?? 0,
    last_sync_error: opcoes.last_sync_error || "",
    lastSyncError: opcoes.last_sync_error || "",
    recovery_source: opcoes.recovery_source || "",
    recoverySource: opcoes.recovery_source || "",
    recovered_at: opcoes.recovered_at || "",
    recoveredAt: opcoes.recovered_at || "",
    reconciliation_version: FINANCIAL_RECONCILIATION_VERSION,
    reconciliationVersion: FINANCIAL_RECONCILIATION_VERSION,
    processing_node: opcoes.processing_node || getPlataformaDispositivoOperacional(),
    processingNode: opcoes.processing_node || getPlataformaDispositivoOperacional(),
    worker_version: FINANCIAL_WORKER_VERSION,
    workerVersion: FINANCIAL_WORKER_VERSION,
    worker_node: opcoes.worker_node || `${getPlataformaDispositivoOperacional()}:${deviceId}`,
    workerNode: opcoes.worker_node || `${getPlataformaDispositivoOperacional()}:${deviceId}`,
    retry_strategy: opcoes.retry_strategy || "exponential",
    retryStrategy: opcoes.retry_strategy || "exponential",
    retry_backoff_level: opcoes.retry_backoff_level ?? 0,
    retryBackoffLevel: opcoes.retry_backoff_level ?? 0,
    processing_priority: opcoes.processing_priority ?? 0,
    processingPriority: opcoes.processing_priority ?? 0,
    app_version: APP_VERSION,
    appVersion: APP_VERSION,
    pwa_version: APP_VERSION,
    pwaVersion: APP_VERSION,
    sync_source: offline ? "offline_queue" : "online",
    syncSource: offline ? "offline_queue" : "online",
    offline_created_at: offline ? agora : "",
    offlineCreatedAt: offline ? agora : "",
    synced_at: "",
    syncedAt: "",
    device_platform: getPlataformaDispositivoOperacional(),
    devicePlatform: getPlataformaDispositivoOperacional(),
    shadow_validation_json: {
      mode: "shadow",
      legacyFlow: "active",
      atomicFlow: "prepared",
      generatedAt: agora
    },
    shadowValidation: {
      mode: "shadow",
      legacyFlow: "active",
      atomicFlow: "prepared",
      generatedAt: agora
    }
  };
}

function registrarShadowFinanceiroLocal(tipo, detalhes = {}) {
  try {
    registrarDiagnostico("financeiro-shadow", tipo, JSON.stringify({
      ...detalhes,
      financial_flow_version: FINANCIAL_FLOW_VERSION,
      app_version: APP_VERSION,
      device_id: deviceId
    }).slice(0, 900), { silent: true });
  } catch (_) {}
}

function getRegistroSyncId(colecao, registro = {}) {
  const id = registro.remote_id || registro.remoteId || registro.id || registro.local_id || registro.localId;
  if (id !== undefined && id !== null && String(id).trim()) return String(id);
  const base = [
    colecao,
    registro.cliente || registro.nome || registro.descricao || registro.tipo || "registro",
    registro.data || registro.criadoEm || registro.createdAt || registro.updated_at || Date.now()
  ].join("|");
  return base.toLowerCase().replace(/[^a-z0-9_-]+/gi, "-").slice(0, 90);
}

function normalizarPayloadSync(colecao, registro = {}) {
  const atualizadoEm = registro.updated_at || registro.updatedAt || registro.atualizadoEm || registro.criadoEm || registro.createdAt || new Date().toISOString();
  const ownerId = getDataOwnerId();
  return {
    ...registro,
    user_id: pareceUuid(ownerId) ? ownerId : registro.user_id || registro.userId || null,
    owner_id: ownerId,
    source_device_id: registro.source_device_id || registro.sourceDeviceId || deviceId,
    sourceDeviceId: registro.sourceDeviceId || registro.source_device_id || deviceId,
    sync_status: registro.sync_status || registro.syncStatus || "pending",
    updated_at: atualizadoEm,
    updatedAt: registro.updatedAt || atualizadoEm,
    local_collection: colecao
  };
}

function getTimestampAlteracaoRegistro(item = {}) {
  return Date.parse(
    item?.updated_at
    || item?.updatedAt
    || item?.atualizadoEm
    || item?.lastSeenAt
    || item?.last_seen_at
    || item?.data
    || item?.createdAt
    || item?.criadoEm
    || 0
  ) || 0;
}

function coletarClientesOperacionaisParaSync() {
  const mapa = new Map();
  pedidos.forEach((pedido) => {
    const nome = String(clienteDoPedido(pedido) || "").trim();
    if (!nome || nome === "Sem cliente") return;
    const telefone = telefoneDoPedido(pedido);
    const email = emailDoPedido(pedido);
    const chave = normalizarTextoBusca(`${nome}|${telefone || ""}|${email || ""}`);
    const atual = mapa.get(chave) || {
      id: `cliente-${chave.slice(0, 72)}`,
      nome,
      telefone,
      email,
      pedidos: 0,
      total: 0,
      owner_id: pedido.owner_id || getDataOwnerId(),
      sync_status: pedido.sync_status || "pending",
      updated_at: pedido.updated_at || pedido.updatedAt || pedido.criadoEm || new Date().toISOString()
    };
    atual.pedidos += 1;
    atual.total += totalPedido(pedido);
    const pedidoAtualizado = Date.parse(pedido.updated_at || pedido.updatedAt || pedido.criadoEm || 0) || 0;
    const atualAtualizado = Date.parse(atual.updated_at || 0) || 0;
    if (pedidoAtualizado > atualAtualizado) atual.updated_at = pedido.updated_at || pedido.updatedAt || pedido.criadoEm;
    if ((pedido.sync_status || "pending") !== "synced") atual.sync_status = "pending";
    mapa.set(chave, atual);
  });
  return Array.from(mapa.values());
}

function getColecaoLocalSync(colecao) {
  if (colecao === "pedidos") return pedidos;
  if (colecao === "estoque") return estoque;
  if (colecao === "caixa") return caixa;
  if (colecao === "clientes") return coletarClientesOperacionaisParaSync();
  return [];
}

function coletarRegistrosPendentesLocais() {
  const itens = [];
  SYNCABLE_COLLECTIONS.forEach((colecao) => {
    getColecaoLocalSync(colecao).forEach((registro) => {
      const status = String(registro.sync_status || registro.syncStatus || "pending").toLowerCase();
      if (!["pending", "error"].includes(status)) return;
      const payload = normalizarPayloadSync(colecao, registro);
      itens.push({
        id: `${colecao}:${getRegistroSyncId(colecao, payload)}`,
        scopeId: getEscopoDadosAtual(),
        collection: colecao,
        recordId: getRegistroSyncId(colecao, payload),
        data: payload,
        operation: payload.deleted_at ? "delete" : "upsert",
        status: "pending",
        attempts: 0,
        updatedAt: payload.updated_at || new Date().toISOString()
      });
    });
  });
  return itens;
}

function salvarFilaSyncLocal() {
  const escopo = getEscopoDadosAtual();
  const fila = escopo
    ? (Array.isArray(pendingSync) ? pendingSync : []).filter((item) => !item.scopeId || item.scopeId === escopo).map((item) => ({ ...item, scopeId: escopo }))
    : (Array.isArray(pendingSync) ? pendingSync : []);
  pendingSync = fila;
  localStorage.setItem(getChaveFilaSyncUsuario(escopo), JSON.stringify(fila));
  if (escopo) localStorage.removeItem(PENDING_SYNC_QUEUE_KEY);
}

function recomporFilaSyncPendente() {
  const escopo = getEscopoDadosAtual();
  const mapa = new Map();
  (Array.isArray(pendingSync) ? pendingSync : []).forEach((item) => {
    if (!item?.collection || !item?.recordId) return;
    if (escopo && item.scopeId && item.scopeId !== escopo) return;
    const normalizado = escopo ? { ...item, scopeId: escopo } : item;
    mapa.set(`${normalizado.scopeId || "local"}:${normalizado.collection}:${normalizado.recordId}`, normalizado);
  });
  coletarRegistrosPendentesLocais().forEach((item) => {
    if (escopo && item.scopeId !== escopo) return;
    const chave = `${item.scopeId || "local"}:${item.collection}:${item.recordId}`;
    const existente = mapa.get(chave) || {};
    mapa.set(chave, { ...existente, ...item, attempts: existente.attempts || 0, scopeId: item.scopeId || escopo || "" });
  });
  pendingSync = Array.from(mapa.values()).filter((item) => item.status !== "synced" && (!escopo || item.scopeId === escopo));
  salvarFilaSyncLocal();
  return pendingSync;
}

function atualizarStatusRegistroLocalSync(colecao, recordId, status, extra = {}) {
  const atualizar = (registro) => {
    if (getRegistroSyncId(colecao, registro) !== String(recordId)) return registro;
    return {
      ...registro,
      ...extra,
      sync_status: status,
      syncStatus: status,
      remote_id: extra.remote_id || extra.remoteId || registro.remote_id || registro.remoteId || String(recordId),
      synced_at: status === "synced" ? new Date().toISOString() : registro.synced_at || "",
      sync_error: status === "error" ? String(extra.sync_error || extra.syncError || registro.sync_error || "").slice(0, 240) : ""
    };
  };
  if (colecao === "pedidos") pedidos = pedidos.map(atualizar);
  if (colecao === "estoque") estoque = estoque.map(atualizar);
  if (colecao === "caixa") caixa = caixa.map(atualizar);
}

async function enviarRegistroSyncSupabase(item) {
  const escopo = getEscopoDadosAtual();
  if (escopo && item.scopeId && item.scopeId !== escopo) {
    throw new Error("Fila offline pertence a outra conta.");
  }
  const payload = normalizarPayloadSync(item.collection, item.data || {});
  debugInfo("[SyncQueue][send]", {
    auth_uid: syncConfig.supabaseUserId || "",
    scope_id: item.scopeId || escopo || "",
    collection: item.collection,
    record_id: item.recordId,
    sync_status: payload.sync_status || "pending"
  });
  return requisicaoSupabase("/rest/v1/rpc/upsert_erp_record_if_newer", {
    method: "POST",
    body: JSON.stringify({
      p_collection: item.collection,
      p_record_id: String(item.recordId),
      p_data: payload,
      p_deleted_at: payload.deleted_at || null
    })
  });
}

async function sincronizarFilaOfflinePendente(motivo = "manual") {
  if (!estaOnline()) {
    recomporFilaSyncPendente();
    syncConfig.autoBackupStatus = "Offline - fila pendente";
    salvarDados();
    return { ok: false, offline: true, pending: pendingSync.length };
  }
  if (!syncConfig.supabaseAccessToken || !syncConfig.supabaseUserId) {
    recomporFilaSyncPendente();
    return { ok: false, auth: false, pending: pendingSync.length };
  }

  recomporFilaSyncPendente();
  if (!pendingSync.length) return { ok: true, sent: 0, pending: 0 };

  let enviados = 0;
  const restantes = [];
  for (const item of pendingSync) {
    try {
      const resultado = await enviarRegistroSyncSupabase(item);
      const action = String(resultado?.action || resultado?.status || "synced");
      atualizarStatusRegistroLocalSync(item.collection, item.recordId, "synced", {
        remote_id: resultado?.remote_id || item.recordId,
        sync_result: action
      });
      enviados += 1;
      debugInfo("[SyncQueue][ok]", {
        motivo,
        collection: item.collection,
        record_id: item.recordId,
        action,
        sync_status: "synced"
      });
    } catch (erro) {
      const falha = {
        ...item,
        status: "error",
        attempts: Number(item.attempts || 0) + 1,
        lastError: String(erro.message || erro).slice(0, 240),
        updatedAt: new Date().toISOString()
      };
      atualizarStatusRegistroLocalSync(item.collection, item.recordId, "error", { sync_error: falha.lastError });
      restantes.push(falha);
      registrarDiagnostico("sync", `Falha ao sincronizar ${item.collection}/${item.recordId}`, falha.lastError);
      break;
    }
  }
  pendingSync = restantes.concat(pendingSync.slice(enviados + restantes.length).filter((item) => item.status !== "synced"));
  syncConfig.autoBackupStatus = restantes.length ? "Fila com erro" : "Fila sincronizada";
  syncConfig.ultimaSync = new Date().toISOString();
  salvarDados();
  return { ok: restantes.length === 0, sent: enviados, pending: pendingSync.length };
}

function realtimeSyncDisponivel() {
  return REALTIME_SYNC_ENABLED
    && typeof WebSocket !== "undefined"
    && !!syncConfig.supabaseAccessToken
    && !!syncConfig.supabaseUserId
    && !!syncConfig.supabaseUrl
    && estaOnline();
}

function montarUrlRealtimeSupabase() {
  const base = normalizarUrlSupabase(syncConfig.supabaseUrl || SUPABASE_DEFAULT_URL).replace(/^http/i, "ws");
  const anonKey = encodeURIComponent(syncConfig.supabaseAnonKey || SUPABASE_DEFAULT_ANON_KEY);
  return `${base}/realtime/v1/websocket?apikey=${anonKey}&vsn=2.0.0`;
}

function montarConfigRealtimeUsuario(userId) {
  const filtroUsuario = `user_id=eq.${userId}`;
  return {
    broadcast: { ack: false, self: false },
    presence: { enabled: false },
    postgres_changes: [
      { event: "INSERT", schema: "public", table: "erp_backups", filter: filtroUsuario },
      { event: "UPDATE", schema: "public", table: "erp_backups", filter: filtroUsuario },
      { event: "INSERT", schema: "public", table: "erp_records", filter: filtroUsuario },
      { event: "UPDATE", schema: "public", table: "erp_records", filter: filtroUsuario },
      { event: "INSERT", schema: "public", table: "subscriptions", filter: filtroUsuario },
      { event: "UPDATE", schema: "public", table: "subscriptions", filter: filtroUsuario },
      { event: "INSERT", schema: "public", table: "payments", filter: filtroUsuario },
      { event: "UPDATE", schema: "public", table: "payments", filter: filtroUsuario },
      { event: "INSERT", schema: "public", table: "user_message_notifications", filter: filtroUsuario },
      { event: "UPDATE", schema: "public", table: "user_message_notifications", filter: filtroUsuario },
      { event: "DELETE", schema: "public", table: "user_message_notifications", filter: filtroUsuario }
    ],
    private: false
  };
}

function proximoRefRealtime() {
  realtimeSyncState.ref += 1;
  return String(realtimeSyncState.ref);
}

function enviarMensagemRealtime(evento, payload = {}, opcoes = {}) {
  const socket = realtimeSyncState.socket;
  if (!socket || socket.readyState !== WebSocket.OPEN) return "";
  const ref = proximoRefRealtime();
  const topic = opcoes.topic || realtimeSyncState.topic;
  let joinRef = Object.prototype.hasOwnProperty.call(opcoes, "joinRef") ? opcoes.joinRef : (realtimeSyncState.joinRef || null);
  if (evento === "phx_join") {
    joinRef = ref;
    realtimeSyncState.joinRef = joinRef;
  }
  socket.send(JSON.stringify([joinRef, ref, topic, evento, payload]));
  return ref;
}

function iniciarHeartbeatRealtime() {
  if (realtimeSyncState.heartbeatTimer) clearInterval(realtimeSyncState.heartbeatTimer);
  realtimeSyncState.heartbeatTimer = setInterval(() => {
    enviarMensagemRealtime("heartbeat", {}, { topic: "phoenix", joinRef: null });
  }, REALTIME_SYNC_HEARTBEAT_MS);
}

function limparTimersRealtime() {
  if (realtimeSyncState.heartbeatTimer) clearInterval(realtimeSyncState.heartbeatTimer);
  if (realtimeSyncState.reconnectTimer) clearTimeout(realtimeSyncState.reconnectTimer);
  if (realtimeSyncState.debounceTimer) clearTimeout(realtimeSyncState.debounceTimer);
  if (realtimeSyncState.pollTimer) clearInterval(realtimeSyncState.pollTimer);
  realtimeSyncState.heartbeatTimer = null;
  realtimeSyncState.reconnectTimer = null;
  realtimeSyncState.debounceTimer = null;
  realtimeSyncState.pollTimer = null;
}

function pararRealtimeSyncUsuario(motivo = "logout") {
  const socket = realtimeSyncState.socket;
  limparTimersRealtime();
  if (socket && socket.readyState === WebSocket.OPEN) {
    try {
      enviarMensagemRealtime("phx_leave", {}, { joinRef: realtimeSyncState.joinRef || null });
    } catch (_) {}
  }
  if (socket && [WebSocket.CONNECTING, WebSocket.OPEN].includes(socket.readyState)) {
    try {
      socket.close(1000, motivo);
    } catch (_) {}
  }
  realtimeSyncState = {
    socket: null,
    topic: "",
    userId: "",
    accessToken: "",
    ref: 0,
    joinRef: "",
    joined: false,
    heartbeatTimer: null,
    reconnectTimer: null,
    debounceTimer: null,
    pollTimer: null,
    applying: false,
    lastEventKey: "",
    lastEventAt: 0,
    lastPollAt: 0,
    lastToastAt: realtimeSyncState.lastToastAt || 0,
    reconnectAttempts: 0
  };
  registrarDiagnostico("Realtime", "Subscription encerrada", motivo);
}

function agendarReconnectRealtime(motivo = "socket-close") {
  if (!REALTIME_SYNC_ENABLED) return;
  if (!syncConfig.supabaseAccessToken || !syncConfig.supabaseUserId || !estaOnline()) return;
  if (realtimeSyncState.reconnectTimer) clearTimeout(realtimeSyncState.reconnectTimer);
  const tentativas = Math.min(6, Number(realtimeSyncState.reconnectAttempts || 0) + 1);
  realtimeSyncState.reconnectAttempts = tentativas;
  const atraso = REALTIME_SYNC_RECONNECT_MS * tentativas;
  realtimeSyncState.reconnectTimer = setTimeout(() => {
    realtimeSyncState.reconnectTimer = null;
    iniciarRealtimeSyncUsuario(`reconnect:${motivo}`).catch((erro) => {
      registrarDiagnostico("Realtime", "Reconnect falhou", erro.message || erro);
    });
  }, atraso);
}

async function iniciarRealtimeSyncUsuario(motivo = "manual") {
  if (!REALTIME_SYNC_ENABLED) return false;
  if (!realtimeSyncDisponivel()) return false;
  const userId = String(syncConfig.supabaseUserId || "").trim();
  const token = String(syncConfig.supabaseAccessToken || "").trim();
  const socketAtual = realtimeSyncState.socket;
  if (
    socketAtual
    && realtimeSyncState.userId === userId
    && realtimeSyncState.accessToken === token
    && [WebSocket.CONNECTING, WebSocket.OPEN].includes(socketAtual.readyState)
  ) {
    agendarPollingSyncTempoReal(`realtime-already:${motivo}`);
    return true;
  }

  if (socketAtual) pararRealtimeSyncUsuario("troca-de-sessao");

  const topic = `realtime:simplifica-sync-${userId}`;
  const socket = new WebSocket(montarUrlRealtimeSupabase());
  realtimeSyncState.socket = socket;
  realtimeSyncState.topic = topic;
  realtimeSyncState.userId = userId;
  realtimeSyncState.accessToken = token;
  realtimeSyncState.joined = false;

  socket.onopen = () => {
    realtimeSyncState.reconnectAttempts = 0;
    enviarMensagemRealtime("phx_join", {
      config: montarConfigRealtimeUsuario(userId),
      access_token: token
    }, { joinRef: null });
    iniciarHeartbeatRealtime();
    agendarPollingSyncTempoReal(`realtime:${motivo}`);
    debugInfo("[Realtime][join]", { motivo, auth_uid: userId, tables: ["erp_backups", "erp_records", "subscriptions", "payments", "user_message_notifications"] });
    carregarNotificacoesMensagensRemotas(true).catch(() => {});
    sincronizarRelayNotificacoesAndroid().catch(() => {});
  };

  socket.onmessage = (event) => {
    tratarMensagemRealtimeSupabase(event.data);
  };

  socket.onerror = () => {
    registrarDiagnostico("Realtime", "Erro no WebSocket", motivo);
  };

  socket.onclose = () => {
    if (realtimeSyncState.socket !== socket) return;
    if (realtimeSyncState.heartbeatTimer) clearInterval(realtimeSyncState.heartbeatTimer);
    if (realtimeSyncState.debounceTimer) clearTimeout(realtimeSyncState.debounceTimer);
    realtimeSyncState.socket = null;
    realtimeSyncState.joined = false;
    realtimeSyncState.heartbeatTimer = null;
    realtimeSyncState.debounceTimer = null;
    agendarPollingSyncTempoReal("realtime-close");
    agendarReconnectRealtime("close");
  };

  return true;
}

function extrairMensagemRealtime(raw) {
  try {
    const mensagem = typeof raw === "string" ? JSON.parse(raw) : raw;
    if (Array.isArray(mensagem)) {
      return {
        joinRef: mensagem[0],
        ref: mensagem[1],
        topic: mensagem[2],
        event: mensagem[3],
        payload: mensagem[4] || {}
      };
    }
    return mensagem && typeof mensagem === "object" ? mensagem : null;
  } catch (erro) {
    registrarDiagnostico("Realtime", "Mensagem invalida", erro.message);
    return null;
  }
}

function normalizarEventoPostgresRealtime(payload = {}) {
  const data = payload.data && typeof payload.data === "object" ? payload.data : payload;
  return {
    ids: payload.ids || data.ids || [],
    schema: data.schema || "public",
    table: data.table || "",
    type: data.type || payload.type || "",
    commit_timestamp: data.commit_timestamp || payload.commit_timestamp || "",
    record: data.record && typeof data.record === "object" ? data.record : {},
    old_record: data.old_record && typeof data.old_record === "object" ? data.old_record : {},
    errors: data.errors || payload.errors || null
  };
}

function eventoRealtimePertenceAoUsuario(evento) {
  const userId = String(syncConfig.supabaseUserId || "").trim();
  if (!userId) return false;
  const clientId = String(billingConfig.clientId || getUsuarioAtual()?.clientId || "").trim();
  const record = evento.record || {};
  const oldRecord = evento.old_record || {};
  const data = record.data && typeof record.data === "object" ? record.data : {};
  const oldData = oldRecord.data && typeof oldRecord.data === "object" ? oldRecord.data : {};
  const candidatosUsuario = [
    record.user_id,
    record.owner_id,
    oldRecord.user_id,
    oldRecord.owner_id,
    data.user_id,
    data.owner_id,
    oldData.user_id,
    oldData.owner_id
  ].filter((valor) => valor !== undefined && valor !== null).map((valor) => String(valor));
  if (candidatosUsuario.includes(userId)) return true;
  const candidatosCliente = [
    record.client_id,
    oldRecord.client_id,
    data.client_id,
    data.clientId,
    oldData.client_id,
    oldData.clientId
  ].filter((valor) => valor !== undefined && valor !== null).map((valor) => String(valor));
  return !!clientId && candidatosCliente.includes(clientId);
}

function eventoRealtimeEhDesteDispositivo(evento) {
  if (!["erp_backups", "erp_records"].includes(evento.table)) return false;
  const record = evento.record || {};
  if (evento.table === "erp_backups" && String(record.device_id || "") === deviceId) return true;
  const data = record.data && typeof record.data === "object" ? record.data : {};
  return [
    data.source_device_id,
    data.sourceDeviceId,
    data.device_id,
    data.deviceId,
    data.sync_device_id
  ].filter(Boolean).some((valor) => String(valor) === deviceId);
}

function tratarMensagemRealtimeSupabase(raw) {
  const mensagem = extrairMensagemRealtime(raw);
  if (!mensagem) return;

  if (mensagem.event === "phx_reply") {
    const respostaJoin = mensagem.topic === realtimeSyncState.topic && mensagem.ref === realtimeSyncState.joinRef;
    if (mensagem.payload?.status === "ok" && respostaJoin) {
      realtimeSyncState.joined = true;
      registrarDiagnostico("Realtime", "Subscription ativa", realtimeSyncState.topic);
    } else if (mensagem.payload?.status === "error" && respostaJoin) {
      registrarDiagnostico("Realtime", "Falha ao assinar canal", JSON.stringify(mensagem.payload.response || {}));
    }
    return;
  }

  if (mensagem.event === "system") {
    if (mensagem.payload?.status === "error" || mensagem.payload?.status === "timeout") {
      registrarDiagnostico("Realtime", "Sistema reportou falha", mensagem.payload.message || mensagem.payload.status);
    }
    return;
  }

  if (mensagem.event === "postgres_changes") {
    tratarEventoRealtimeSupabase(normalizarEventoPostgresRealtime(mensagem.payload));
    return;
  }

  if (mensagem.event === "phx_close" || mensagem.event === "phx_error") {
    registrarDiagnostico("Realtime", "Canal fechado pelo servidor", mensagem.event);
  }
}

function tratarEventoRealtimeSupabase(evento) {
  if (!["erp_backups", "erp_records", "subscriptions", "payments", "user_message_notifications"].includes(evento.table)) return;
  if (!eventoRealtimePertenceAoUsuario(evento)) return;
  if (eventoRealtimeEhDesteDispositivo(evento)) return;

  const recordId = evento.record?.id || evento.record?.record_id || evento.old_record?.id || evento.old_record?.record_id || "";
  const eventKey = [evento.table, evento.type, evento.commit_timestamp, recordId].join(":");
  if (eventKey === realtimeSyncState.lastEventKey && Date.now() - realtimeSyncState.lastEventAt < 2500) return;
  realtimeSyncState.lastEventKey = eventKey;
  realtimeSyncState.lastEventAt = Date.now();

  if (realtimeSyncState.debounceTimer) clearTimeout(realtimeSyncState.debounceTimer);
  realtimeSyncState.debounceTimer = setTimeout(() => {
    realtimeSyncState.debounceTimer = null;
    processarMudancaRealtimeSupabase(evento).catch((erro) => {
      registrarDiagnostico("Realtime", "Falha ao aplicar evento remoto", erro.message || erro);
    });
  }, REALTIME_SYNC_DEBOUNCE_MS);
}

function getListaColecaoOperacional(colecao) {
  if (colecao === "pedidos") return pedidos;
  if (colecao === "estoque") return estoque;
  if (colecao === "caixa") return caixa;
  if (colecao === "orcamentos") return orcamentos;
  return null;
}

function setListaColecaoOperacional(colecao, lista) {
  if (!Array.isArray(lista)) return false;
  if (colecao === "pedidos") pedidos = lista;
  else if (colecao === "estoque") estoque = lista;
  else if (colecao === "caixa") caixa = lista;
  else if (colecao === "orcamentos") orcamentos = lista;
  else return false;
  return true;
}

function aplicarRegistroRemotoRealtime(record = {}) {
  const colecao = String(record.collection || "").trim();
  const lista = getListaColecaoOperacional(colecao);
  if (!lista) return false;
  if (String(record.user_id || record.owner_id || "") !== String(syncConfig.supabaseUserId || "")) return false;

  const data = record.data && typeof record.data === "object" ? record.data : {};
  const recordId = String(record.record_id || data.remote_id || data.remoteId || data.id || "").trim();
  if (!recordId) return false;
  const indice = lista.findIndex((item) => getRegistroSyncId(colecao, item) === recordId || String(item?.id || "") === recordId);
  const local = indice >= 0 ? lista[indice] : null;
  const statusLocal = String(local?.sync_status || local?.syncStatus || "synced").toLowerCase();
  const localPendente = ["pending", "error"].includes(statusLocal);
  const tsLocal = getTimestampAlteracaoRegistro(local || {});
  const tsRemoto = getTimestampAlteracaoRegistro(data) || Date.parse(record.updated_at || record.created_at || 0) || 0;
  if (localPendente && tsLocal >= tsRemoto) return false;

  let novaLista;
  if (record.deleted_at || data.deleted_at) {
    novaLista = lista.filter((item) => getRegistroSyncId(colecao, item) !== recordId && String(item?.id || "") !== recordId);
  } else {
    const atualizadoEm = data.updated_at || data.updatedAt || record.updated_at || record.created_at || new Date().toISOString();
    const itemRemoto = {
      ...data,
      id: data.id || recordId,
      user_id: syncConfig.supabaseUserId,
      owner_id: syncConfig.supabaseUserId,
      remote_id: recordId,
      sync_status: "synced",
      syncStatus: "synced",
      updated_at: atualizadoEm,
      updatedAt: data.updatedAt || atualizadoEm,
      synced_at: new Date().toISOString(),
      sync_error: ""
    };
    novaLista = indice >= 0
      ? lista.map((item, idx) => (idx === indice ? itemRemoto : item))
      : lista.concat(itemRemoto);
  }

  return setListaColecaoOperacional(colecao, novaLista);
}

function avisarRealtimeDadosAtualizados() {
  const agora = Date.now();
  if (agora - Number(realtimeSyncState.lastToastAt || 0) < 3500) return;
  realtimeSyncState.lastToastAt = agora;
  if (typeof mostrarToast === "function") mostrarToast("Atualizado", "info", 2200);
}

function avisarRealtimePlanoAtualizado() {
  const agora = Date.now();
  if (agora - Number(realtimeSyncState.lastToastAt || 0) < 3500) return;
  realtimeSyncState.lastToastAt = agora;
  if (typeof mostrarToast === "function") mostrarToast("Plano atualizado", "info", 2400);
}

async function processarMudancaBillingRealtimeSupabase(evento) {
  registrarDiagnostico("Realtime", isSuperAdmin() ? "Evento de billing recebido" : "Plano atualizado em tempo real", `${evento.table}:${evento.type || ""}`);
  const licenca = await consultarLicencaSupabaseSilencioso({ motivo: `realtime-${evento.table}` });
  if (isSuperAdmin() && ["clientes", "superadmin", "admin"].includes(telaAtual)) {
    await carregarSaasSupabaseSilencioso({ renderizar: false, feedback: false }).catch((erro) => {
      registrarDiagnostico("Realtime", "Empresas SaaS não atualizadas via billing", erro.message || erro);
    });
  }
  if (licenca && document.visibilityState !== "hidden") {
    if (["assinatura", "minhaAssinatura", "planos", "admin", "clientes", "dashboard"].includes(telaAtual)) agendarRenderizacaoPreservandoScroll(120);
    avisarRealtimePlanoAtualizado();
  }
  return !!licenca;
}

async function processarMudancaRealtimeSupabase(evento) {
  if (realtimeSyncState.applying || !syncConfig.supabaseAccessToken || !syncConfig.supabaseUserId || !estaOnline()) return false;
  realtimeSyncState.applying = true;
  try {
    if (evento.table === "user_message_notifications") {
      aplicarEventoNotificacaoMensagemRealtime(evento);
      return true;
    }
    if (["subscriptions", "payments"].includes(evento.table)) {
      return await processarMudancaBillingRealtimeSupabase(evento);
    }

    const pendentes = recomporFilaSyncPendente();
    if (pendentes.length) {
      registrarDiagnostico("Realtime", "Evento remoto aguardou fila local", `${pendentes.length} item(ns) pendente(s)`);
      const sincronizado = await sincronizarSupabaseSilencioso();
      if (sincronizado) avisarRealtimeDadosAtualizados();
      return !!sincronizado;
    }

    let alterou = false;
    if (evento.table === "erp_records") {
      alterou = aplicarRegistroRemotoRealtime(evento.record) || alterou;
    }

    await new Promise((resolve) => setTimeout(resolve, 350));
    const remoto = await obterBackupSupabase();
    if (remoto) {
      alterou = aplicarBackup(remoto, "mesclar") || alterou;
    }

    if (alterou) {
      marcarSincronizacaoVisual("realtime");
      syncConfig.autoBackupStatus = "Atualizado";
      salvarCacheDadosUsuario();
      salvarDados();
      if (document.visibilityState !== "hidden") agendarRenderizacaoPreservandoScroll(120);
      avisarRealtimeDadosAtualizados();
    }
    return alterou;
  } finally {
    realtimeSyncState.applying = false;
  }
}

async function baixarAtualizacoesSupabaseSilencioso(motivo = "polling") {
  if (!syncConfig.supabaseAccessToken || !syncConfig.supabaseUserId || !estaOnline()) return false;
  if (realtimeSyncState.applying) return false;
  realtimeSyncState.applying = true;
  try {
    let alterou = false;
    const registros = await obterRegistrosErpSupabase();
    alterou = aplicarRegistrosErpSupabase(registros) || alterou;
    const remoto = await obterBackupSupabase();
    if (remoto) alterou = aplicarBackup(remoto, "mesclar") || alterou;
    if (alterou) {
      marcarSincronizacaoVisual(motivo);
      syncConfig.autoBackupStatus = "Atualizado";
      salvarCacheDadosUsuario();
      salvarDados();
      if (document.visibilityState !== "hidden") agendarRenderizacaoPreservandoScroll(120);
      avisarRealtimeDadosAtualizados();
    }
    return alterou;
  } catch (erro) {
    registrarDiagnostico("sync", "Polling de sincronização falhou", erro.message || erro);
    return false;
  } finally {
    realtimeSyncState.applying = false;
  }
}

async function executarPollingSyncTempoReal(motivo = "polling") {
  if (!syncConfig.supabaseAccessToken || !syncConfig.supabaseUserId || !estaOnline()) return false;
  const agora = Date.now();
  const intervaloMinimo = document.visibilityState === "hidden" ? REALTIME_FALLBACK_BACKGROUND_MS : REALTIME_FALLBACK_FOREGROUND_MS;
  if (agora - Number(realtimeSyncState.lastPollAt || 0) < Math.max(8000, intervaloMinimo - 1000)) return false;
  realtimeSyncState.lastPollAt = agora;
  const pendentes = recomporFilaSyncPendente();
  if (pendentes.length) {
    return !!await sincronizarSupabaseSilencioso().catch((erro) => {
      registrarDiagnostico("sync", "Polling não enviou fila pendente", erro.message || erro);
      return false;
    });
  }
  return baixarAtualizacoesSupabaseSilencioso(motivo);
}

function agendarPollingSyncTempoReal(motivo = "session") {
  if (!REALTIME_SYNC_ENABLED) return false;
  if (!syncConfig.supabaseAccessToken || !syncConfig.supabaseUserId) return false;
  if (realtimeSyncState.pollTimer) clearInterval(realtimeSyncState.pollTimer);
  const intervalo = document.visibilityState === "hidden" ? REALTIME_FALLBACK_BACKGROUND_MS : REALTIME_FALLBACK_FOREGROUND_MS;
  realtimeSyncState.pollTimer = setInterval(() => {
    executarPollingSyncTempoReal("fallback-polling").catch((erro) => registrarDiagnostico("sync", "Fallback polling falhou", erro.message || erro));
  }, intervalo);
  if (document.visibilityState !== "hidden") {
    setTimeout(() => executarPollingSyncTempoReal(`fallback-start:${motivo}`).catch(() => {}), 1500);
  }
  return true;
}

function usuarioEhDonoDaLicenca(email) {
  const alvo = normalizarEmail(email);
  const usuario = normalizarUsuarios(usuarios).find((item) => item.email === alvo);
  return usuario?.papel === "superadmin";
}

function dispositivoDentroDoLimite(email = getEmailLicencaAtual()) {
  const emailLicenca = normalizarEmail(email);
  if (!emailLicenca || usuarioEhDonoDaLicenca(emailLicenca)) return true;

  const tipo = detectarTipoDispositivo();
  const limites = getLimitesDispositivos();
  const lista = normalizarDispositivosLicenca();
  if (lista.some((item) => item.email === emailLicenca && item.tipo === tipo && item.id === deviceId)) return true;
  return lista.filter((item) => item.email === emailLicenca).length < limites.total;
}

function registrarDispositivoLicenca(email = getEmailLicencaAtual(), silencioso = false) {
  const emailLicenca = normalizarEmail(email);
  if (!emailLicenca) {
    if (!silencioso) alert("Informe o e-mail da conta/licença antes de vincular este aparelho.");
    return false;
  }

  const tipo = detectarTipoDispositivo();
  const limites = getLimitesDispositivos();
  const lista = normalizarDispositivosLicenca();
  const atual = lista.find((item) => item.email === emailLicenca && item.tipo === tipo && item.id === deviceId);
  const usuarioDono = usuarioEhDonoDaLicenca(emailLicenca);

  const agora = new Date().toISOString();
  const nome = syncConfig.deviceName || nomeTipoDispositivo(tipo);
  const proximaLista = lista.filter((item) => !(item.email === emailLicenca && item.tipo === tipo && item.id === deviceId));
  proximaLista.unshift({
    id: deviceId,
    email: emailLicenca,
    tipo,
    nome,
    ultimoAcesso: agora
  });

  let fechados = 0;
  const porEmail = proximaLista.filter((item) => item.email === emailLicenca)
    .sort((a, b) => (Date.parse(b.ultimoAcesso || 0) || 0) - (Date.parse(a.ultimoAcesso || 0) || 0));
  const permitidos = new Set((usuarioDono ? porEmail : porEmail.slice(0, limites.total)).map((item) => `${item.email}:${item.tipo}:${item.id}`));
  const filtrada = proximaLista.filter((item) => {
    if (item.email !== emailLicenca || usuarioDono) return true;
    const manter = permitidos.has(`${item.email}:${item.tipo}:${item.id}`);
    if (!manter) fechados += 1;
    return manter;
  });

  billingConfig.registeredDevices = filtrada.slice(0, 30);
  if (fechados > 0 && !silencioso) {
    mostrarToast("Sua conta atingiu o limite de dispositivos conectados para este plano.", "aviso", 5200);
  }
  salvarDados();
  return true;
}

function registrarSessaoSaasLocal(usuario = getUsuarioAtual()) {
  if (!usuario || usuario.papel === "superadmin") return true;
  const clientId = usuario.clientId || billingConfig.clientId;
  if (!clientId) return true;

  const agora = new Date().toISOString();
  const limite = getSessionLimitPlano();
  const janelaAtiva = Date.now() - SECURITY_SESSION_TIMEOUT_MS * 2;
  saasSessions = saasSessions.map(normalizarSessaoSaas).map((sessao) => {
    if ((Date.parse(sessao.lastSeenAt || 0) || 0) < janelaAtiva) {
      return { ...sessao, active: false, endedAt: sessao.endedAt || agora };
    }
    return sessao;
  });

  let atual = saasSessions.find((sessao) => sessao.clientId === clientId && sessao.deviceId === deviceId && sessao.active);
  if (!atual) {
    atual = normalizarSessaoSaas({
      clientId,
      userId: usuario.id,
      deviceId,
      userAgent: navigator.userAgent || "",
      startedAt: agora,
      lastSeenAt: agora,
      active: true
    });
    saasSessions.push(atual);
  } else {
    atual.userId = usuario.id;
    atual.lastSeenAt = agora;
    atual.atualizadoEm = agora;
    atual.updatedAt = agora;
    atual.userAgent = navigator.userAgent || atual.userAgent;
    atual.active = true;
  }

  const ativas = saasSessions
    .filter((sessao) => sessao.clientId === clientId && sessao.active)
    .sort((a, b) => (Date.parse(a.lastSeenAt || 0) || 0) - (Date.parse(b.lastSeenAt || 0) || 0));
  const excedentes = Math.max(0, ativas.length - limite);
  let fechadas = 0;
  ativas.slice(0, excedentes).forEach((sessao) => {
    if (sessao.deviceId === deviceId) return;
    sessao.active = false;
    sessao.endedAt = agora;
    fechadas += 1;
  });

  if (fechadas > 0) {
    registrarAuditoria("múltiplos acessos", { closedSessions: fechadas, limit: limite }, clientId);
    mostrarToast("Sua conta atingiu o limite de dispositivos conectados para este plano.", "aviso", 5200);
  }

  salvarDados();
  return true;
}

async function registrarSessaoSaasOnlineSilencioso(usuario = getUsuarioAtual()) {
  if (!usuario || !syncConfig.supabaseAccessToken || !syncConfig.supabaseUrl || usuario.papel === "superadmin") return;
  try {
    const resultado = await requisicaoSupabase("/rest/v1/rpc/register_saas_session", {
      method: "POST",
      body: JSON.stringify({
        p_device_id: deviceId,
        p_user_agent: navigator.userAgent || ""
      })
    });
    if (Number(resultado?.closed_sessions || 0) > 0) {
      mostrarToast("Sua conta atingiu o limite de dispositivos conectados para este plano.", "aviso", 5200);
    }
  } catch (erro) {
    registrarDiagnostico("Sessão SaaS", "Controle online de sessão não registrado", erro.message);
  }
}

function renderDispositivosLicenca() {
  const email = getEmailLicencaAtual();
  const limites = getLimitesDispositivos();
  const lista = normalizarDispositivosLicenca().filter((item) => item.email === email);
  const linhas = lista.map((item) => `
    <div class="device-row">
      <div>
        <strong>${escaparHtml(nomeTipoDispositivo(item.tipo))}</strong>
        <span class="muted">${escaparHtml(item.nome)} • ${new Date(item.ultimoAcesso).toLocaleDateString("pt-BR")}</span>
      </div>
      <span class="status-badge">${item.id === deviceId ? "Atual" : "Vinculado"}</span>
    </div>
  `).join("") || `<p class="empty">Nenhum aparelho vinculado ainda.</p>`;

  return `
    <div class="device-list">
      <div class="row-title">
        <strong>Aparelhos da licença</strong>
        <span class="muted">${limites.total} sessão(ões) simultânea(s)</span>
      </div>
      ${linhas}
    </div>
  `;
}

function podeGerenciarComercial() {
  return !contaPendenteExclusao() && (isSuperAdmin() || isAdminCliente() || (adminLogado && !getUsuarioAtual()));
}

function formatarMoeda(valor) {
  return moeda.format(Number(valor) || 0);
}

function escaparHtml(valor) {
  return String(valor ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function escaparAttr(valor) {
  return escaparHtml(valor)
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function getMarcaProjetoSrc(tipo = "cover") {
  if (appConfig.brandLogoDataUrl) return appConfig.brandLogoDataUrl;
  return tipo === "icon" ? PROJECT_ICON_IMAGE : PROJECT_COVER_IMAGE;
}

function getMarcaOficialProjetoSrc(tipo = "cover") {
  return tipo === "icon" ? PROJECT_ICON_IMAGE : PROJECT_COVER_IMAGE;
}

function renderMarcaProjeto(classe = "brand-logo", alt = "Marca do projeto", tipo = "") {
  const variant = tipo || (classe.includes("side-brand-logo") ? "icon" : "cover");
  const src = getMarcaProjetoSrc(variant);
  return src ? `<img class="${escaparAttr(classe)}" src="${escaparAttr(src)}" alt="${escaparAttr(alt)}">` : "";
}

function renderMarcaOficialProjeto(classe = "brand-logo", alt = "Simplifica 3D", tipo = "cover") {
  const src = getMarcaOficialProjetoSrc(tipo);
  return src ? `<img class="${escaparAttr(classe)}" src="${escaparAttr(src)}" alt="${escaparAttr(alt)}">` : "";
}

function finalizarIntroAbertura(overlay) {
  if (!overlay || overlay.dataset.done === "true") return;
  overlay.dataset.done = "true";
  try {
    sessionStorage.setItem("simplificaIntroAberturaConcluida", APP_VERSION || "1");
  } catch (_) {}
  overlay.classList.add("is-hidden");
  setTimeout(() => overlay.remove(), 420);
}

function tentarReproduzirIntro(video, overlay) {
  if (!video || !overlay) return;
  video.muted = true;
  video.defaultMuted = true;
  video.setAttribute("muted", "");
  video.setAttribute("playsinline", "");
  video.setAttribute("webkit-playsinline", "");

  const playPromise = video.play?.();
  if (playPromise?.then) {
    playPromise.then(() => {
      overlay.classList.remove("needs-action");
      video.controls = false;
    }).catch((erro) => {
      debugLog("Intro: autoplay bloqueado, aguardando toque do usuario.", erro);
      overlay.classList.add("needs-action");
      video.controls = true;
    });
  }
}

function iniciarIntroAbertura() {
  if (!INTRO_VIDEO_SRC || !document.body) return;
  if (parseStorefrontPublicRoute(location.pathname)) return;
  if (isSuperAdminRoute(location.pathname)) return;
  if (document.getElementById("introOverlay")) return;
  try {
    if (sessionStorage.getItem("simplificaIntroAberturaConcluida")) return;
  } catch (_) {}

  const overlay = document.createElement("div");
  overlay.id = "introOverlay";
  overlay.className = "intro-overlay";
  overlay.setAttribute("role", "presentation");
  overlay.innerHTML = `
    <div class="intro-test-banner" role="status">
      <strong>Versão em testes</strong>
      <span>Estamos validando os últimos ajustes antes do lançamento oficial.</span>
    </div>
    <div class="intro-video-frame" style="aspect-ratio:${escaparAttr(INTRO_VIDEO_ASPECT_RATIO)};width:${escaparAttr(INTRO_VIDEO_FRAME_WIDTH)};height:${escaparAttr(INTRO_VIDEO_FRAME_HEIGHT)};">
      <video class="intro-video" src="${escaparAttr(INTRO_VIDEO_SRC)}" poster="${escaparAttr(PROJECT_COVER_IMAGE)}" autoplay muted playsinline webkit-playsinline preload="auto" style="width:100%;height:100%;max-width:100%;max-height:100%;object-fit:contain;object-position:center;background:#051c26;"></video>
    </div>
    <button class="intro-play" type="button" aria-label="Reproduzir abertura">Reproduzir</button>
    <button class="intro-skip" type="button" aria-label="Pular abertura">Pular</button>
  `;

  const video = overlay.querySelector(".intro-video");
  const play = overlay.querySelector(".intro-play");
  const skip = overlay.querySelector(".intro-skip");
  const concluir = () => finalizarIntroAbertura(overlay);

  if (skip) {
    skip.style.setProperty("position", "fixed", "important");
    skip.style.setProperty("left", "50vw", "important");
    skip.style.setProperty("right", "auto", "important");
    skip.style.setProperty("transform", "translate3d(-50%, 0, 0)", "important");
  }

  if (video) {
    Object.assign(video.style, {
      width: "100%",
      height: "100%",
      maxWidth: "100%",
      maxHeight: "100%",
      objectFit: "contain",
      objectPosition: "center",
      background: "#051c26"
    });
    video.load?.();
  }

  video?.addEventListener("ended", concluir, { once: true });
  video?.addEventListener("error", (erro) => {
    debugLog("Intro: video indisponivel, seguindo para o app.", erro);
    setTimeout(concluir, 700);
  }, { once: true });
  video?.addEventListener("loadeddata", () => tentarReproduzirIntro(video, overlay), { once: true });
  video?.addEventListener("playing", () => {
    overlay.dataset.videoStarted = "true";
  }, { once: true });
  play?.addEventListener("click", () => tentarReproduzirIntro(video, overlay));
  skip?.addEventListener("click", concluir);
  document.body.appendChild(overlay);

  requestAnimationFrame(() => tentarReproduzirIntro(video, overlay));

  setTimeout(() => {
    if (overlay.dataset.done === "true" || overlay.dataset.videoStarted === "true") return;
    if (document.visibilityState === "hidden") concluir();
  }, 2600);
  setTimeout(concluir, 14000);
}

function numeroMonetarioPedido(valor, fallback = 0) {
  if (valor === null || valor === undefined || String(valor).trim() === "") return fallback;
  const texto = String(valor).trim().replace(/[^\d,.-]/g, "");
  const normalizado = texto.includes(",") && texto.lastIndexOf(",") > texto.lastIndexOf(".")
    ? texto.replace(/\./g, "").replace(",", ".")
    : texto.replace(/,/g, "");
  const numero = Number(normalizado);
  return Number.isFinite(numero) ? numero : fallback;
}

function normalizarPercentual(valor = 0) {
  const percentual = Number(valor);
  return Number.isFinite(percentual) ? Math.max(0, percentual) : 0;
}

function calcularValorPercentual(valorBase = 0, percentual = 0) {
  const base = Number(valorBase);
  if (!Number.isFinite(base)) return 0;
  return base * (normalizarPercentual(percentual) / 100);
}

function aplicarPercentualAcrescimo(valorBase = 0, percentual = 0) {
  const base = Number(valorBase);
  if (!Number.isFinite(base)) return 0;
  return base + calcularValorPercentual(base, percentual);
}

function aplicarPercentualDesconto(valorBase = 0, percentual = 0) {
  const base = Number(valorBase);
  if (!Number.isFinite(base)) return 0;
  return Math.max(0, base - calcularValorPercentual(base, percentual));
}

function subtotalItensPedido(origem = {}) {
  const itens = Array.isArray(origem) ? origem : normalizarItensPedido(origem);
  return itens.reduce((soma, item) => {
    const total = numeroMonetarioPedido(item.total, NaN);
    if (Number.isFinite(total) && total > 0) return soma + total;
    const valor = Math.max(0, numeroMonetarioPedido(item.valor ?? item.precoVenda, 0));
    const qtd = Math.max(1, Number(item.qtd) || 1);
    return soma + valor * qtd;
  }, 0);
}

function valorDescontoPedido(pedido = {}) {
  return Math.max(0, numeroMonetarioPedido(pedido?.desconto ?? pedido?.discount ?? pedido?.valor_desconto, 0));
}

function valorEntradaPedido(pedido = {}) {
  return Math.max(0, numeroMonetarioPedido(
    pedido?.down_payment ?? pedido?.valor_entrada ?? pedido?.entradaPaga ?? pedido?.entrada_pago ?? pedido?.entrada ?? pedido?.sinal,
    0
  ));
}

function labelStatusFinanceiroPedido(status = "pendente") {
  const mapa = {
    pendente: "Pendente",
    pago_parcial: "Pago parcial",
    parcial: "Pago parcial",
    pago_total: "Pago total",
    quitado: "Pago total"
  };
  return mapa[String(status || "pendente").toLowerCase()] || "Pendente";
}

function classeStatusFinanceiroPedido(status = "pendente") {
  const valor = String(status || "pendente").toLowerCase();
  if (["pago_total", "quitado"].includes(valor)) return "order-status-paid";
  if (["pago_parcial", "parcial"].includes(valor)) return "order-status-waiting";
  return "order-status-open";
}

function calcularResumoFinanceiroPedido(pedido = {}) {
  const subtotalInformado = numeroMonetarioPedido(pedido?.subtotalItens ?? pedido?.subtotal_itens, NaN);
  const subtotal = Number.isFinite(subtotalInformado) && subtotalInformado >= 0 ? subtotalInformado : subtotalItensPedido(pedido);
  const desconto = valorDescontoPedido(pedido);
  const taxaExtra = Math.max(0, numeroMonetarioPedido(pedido?.taxaExtra ?? pedido?.extraFee ?? pedido?.taxa_extra, 0));
  const totalInformado = numeroMonetarioPedido(pedido?.total ?? pedido?.valor ?? pedido?.totalPedido, NaN);
  const totalCalculado = Math.max(0, subtotal + taxaExtra - desconto);
  const total = Number.isFinite(totalInformado) && totalInformado >= 0 && (totalInformado > 0 || subtotal === 0)
    ? totalInformado
    : totalCalculado;
  const entrada = valorEntradaPedido(pedido);
  const restante = Math.max(0, total - entrada);
  const entradaMaiorQueTotal = entrada > total + 0.009;
  const statusFinanceiro = entrada <= 0 ? "pendente" : restante <= 0 ? "pago_total" : "pago_parcial";
  return { subtotal, desconto, taxaExtra, total, entrada, restante, entradaMaiorQueTotal, statusFinanceiro };
}

function embutirTaxaExtraNosItensCliente(itens = [], taxaExtra = 0) {
  const normalizados = normalizarItensPedido(itens);
  const valorTaxa = Math.max(0, numeroMonetarioPedido(taxaExtra, 0));
  if (!valorTaxa || !normalizados.length) return normalizados;
  const subtotal = subtotalItensPedido(normalizados);
  if (subtotal <= 0) return normalizados;
  let taxaRestante = valorTaxa;
  return normalizados.map((item, indice) => {
    const qtd = Math.max(1, Number(item.qtd) || 1);
    const totalOriginal = Math.max(0, numeroMonetarioPedido(item.total, 0));
    const parcela = indice === normalizados.length - 1
      ? taxaRestante
      : Math.round(valorTaxa * (totalOriginal / subtotal) * 100) / 100;
    taxaRestante = Math.max(0, taxaRestante - parcela);
    const totalCliente = Math.max(0, totalOriginal + parcela);
    return {
      ...item,
      valor: totalCliente / qtd,
      total: totalCliente
    };
  });
}

function totalPedido(pedido) {
  return calcularResumoFinanceiroPedido(pedido || {}).total;
}

function getResumoFinanceiroPedidos(lista = pedidos) {
  return (Array.isArray(lista) ? lista : []).reduce((resumo, pedido) => {
    if (pedidoJaCancelado(pedido)) return resumo;
    const financeiro = calcularResumoFinanceiroPedido(pedido);
    resumo.totalPedidos += financeiro.total;
    resumo.valorRecebido += Math.min(financeiro.entrada, financeiro.total);
    resumo.valorAReceber += financeiro.restante;
    if (financeiro.statusFinanceiro === "pago_total") resumo.pagosTotal += 1;
    else if (financeiro.statusFinanceiro === "pago_parcial") resumo.pagosParcial += 1;
    else resumo.pendentes += 1;
    return resumo;
  }, { totalPedidos: 0, valorRecebido: 0, valorAReceber: 0, pendentes: 0, pagosParcial: 0, pagosTotal: 0 });
}

function clienteDoPedido(pedido) {
  return pedido?.cliente || pedido?.nome || "Sem cliente";
}

function telefoneDoPedido(pedido) {
  return String(pedido?.clienteTelefone || pedido?.telefoneCliente || pedido?.whatsappCliente || pedido?.phone || "").trim();
}

function emailDoPedido(pedido) {
  return String(pedido?.clienteEmail || pedido?.emailCliente || pedido?.customerEmail || pedido?.email || "").trim();
}

function normalizePhoneBR(phone = "") {
  let digits = String(phone || "").replace(/\D/g, "");
  if (!digits) return "";
  if (digits.startsWith("00")) digits = digits.slice(2);
  if (digits.startsWith("0") && (digits.length === 11 || digits.length === 12)) {
    digits = digits.slice(1);
  }
  if ((digits.length === 10 || digits.length === 11) && !digits.startsWith("55")) {
    digits = "55" + digits;
  }
  if (!digits.startsWith("55") || (digits.length !== 12 && digits.length !== 13)) {
    return "";
  }
  return "+" + digits;
}

function normalizarTelefoneWhatsapp(numero = "") {
  return normalizePhoneBR(numero).replace(/^\+/, "");
}

function normalizarTelefoneBusca(numero = "") {
  return String(numero || "").replace(/\D/g, "");
}

function normalizarSugestaoClienteTexto(valor = "") {
  return removerAcentos(String(valor || "").toLowerCase())
    .replace(/[^a-z0-9\s@.+-]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function getCustomerSuggestionUserKey() {
  const usuario = getUsuarioAtual();
  return String(syncConfig.supabaseUserId || usuario?.id || usuario?.email || usuarioAtualEmail || "local").trim() || "local";
}

function getCustomerSuggestionStorageKey() {
  return `recentCustomerSuggestions_${getCustomerSuggestionUserKey()}`;
}

function normalizarSugestaoCliente(item = {}) {
  const name = String(item.name || item.nome || item.displayName || "").trim();
  const phones = Array.isArray(item.phones) ? item.phones : [item.phone || item.telefone || item.number || ""];
  const emails = Array.isArray(item.emails) ? item.emails : [item.email || item.mail || ""];
  const phone = normalizarTelefoneWhatsapp(phones.find(Boolean) || "");
  const email = String(emails.find(Boolean) || "").trim();
  if (!name && !phone && !email) return null;
  return {
    id: String(item.id || item.contactId || `${item.source || "app"}-${name}-${phone}-${email}`).slice(0, 140),
    source: item.source || "app_client",
    name,
    phone,
    email,
    phones: phones.map((valor) => normalizarTelefoneWhatsapp(valor)).filter(Boolean),
    emails: emails.map((valor) => String(valor || "").trim()).filter(Boolean),
    usageCount: Number(item.usageCount || item.pedidos || 0) || 0,
    lastUsedAt: item.lastUsedAt || item.updated_at || item.atualizadoEm || item.createdAt || ""
  };
}

function pontuarSugestaoCliente(sugestao = {}, query = "") {
  const termo = normalizarSugestaoClienteTexto(query);
  const termoTel = normalizarTelefoneBusca(query);
  const nome = normalizarSugestaoClienteTexto(sugestao.name);
  const telefone = normalizarTelefoneBusca(sugestao.phone || sugestao.phones?.[0] || "");
  if (!termo && !termoTel) return 0;
  let score = Number(sugestao.usageCount || 0) * 2;
  if (termoTel.length >= 2 && telefone.includes(termoTel)) score += telefone.startsWith(termoTel) ? 95 : 70;
  if (termo) {
    if (nome === termo) score += 120;
    else if (nome.startsWith(termo)) score += 95;
    else if (nome.split(/\s+/).some((parte) => parte.startsWith(termo))) score += 82;
    else if (nome.includes(termo)) score += 64;
    else {
      let pos = 0;
      for (const letra of termo) {
        pos = nome.indexOf(letra, pos);
        if (pos < 0) return score;
        pos += 1;
      }
      score += 35;
    }
  }
  if (sugestao.source === "app_client") score += 18;
  if (sugestao.source === "phone_contact") score += 8;
  if (sugestao.source === "recent") score += 12;
  return score;
}

function coletarClientesAppParaSugestao() {
  const mapa = new Map();
  const adicionar = (item = {}, source = "app_client") => {
    const sugestao = normalizarSugestaoCliente({
      ...item,
      source,
      name: item.name || item.nome || item.cliente,
      phone: item.phone || item.telefone || item.clienteTelefone,
      email: item.email || item.clienteEmail
    });
    if (!sugestao?.name) return;
    const chave = normalizarSugestaoClienteTexto(`${sugestao.name}|${sugestao.phone || ""}|${sugestao.email || ""}`);
    const atual = mapa.get(chave);
    mapa.set(chave, atual ? { ...atual, usageCount: Math.max(atual.usageCount || 0, sugestao.usageCount || 0) } : sugestao);
  };
  try {
    coletarClientesOperacionaisParaSync().forEach((cliente) => adicionar({
      ...cliente,
      email: cliente.email || cliente.clienteEmail,
      usageCount: cliente.pedidos
    }, "app_client"));
  } catch (_) {}
  pedidos.forEach((pedido) => adicionar({
    id: pedido.id,
    name: clienteDoPedido(pedido),
    phone: telefoneDoPedido(pedido),
    email: emailDoPedido(pedido),
    usageCount: 1,
    lastUsedAt: pedido.updated_at || pedido.updatedAt || pedido.criadoEm
  }, "app_client"));
  if (isSuperAdmin()) {
    saasClients.forEach((cliente) => adicionar({
      id: cliente.id,
      name: cliente.name || cliente.nome || cliente.businessName,
      phone: cliente.phone || cliente.telefone,
      email: cliente.email
    }, "app_client"));
  }
  return Array.from(mapa.values());
}

const CustomerSuggestionManager = {
  searchAppClients(query) {
    return this.rankSuggestions(coletarClientesAppParaSugestao(), query);
  },
  async searchPhoneContacts(query) {
    const plugin = getAIPlugin();
    if (!plugin?.searchPhoneContacts) {
      throw new Error("A agenda do telefone está disponível somente no aplicativo Android instalado.");
    }
    const result = await promiseComTimeout(
      plugin.searchPhoneContacts({ query, limit: 8 }),
      14000,
      "Busca de contatos demorou demais."
    );
    if (result?.granted === false) {
      customerSuggestionState.phoneContactsEnabled = false;
      mostrarToast("Permissão de contatos negada. Vou usar apenas clientes cadastrados.", "aviso", 4200);
      return [];
    }
    customerSuggestionState.phoneContactsEnabled = true;
    return (Array.isArray(result?.contacts) ? result.contacts : [])
      .map((item) => normalizarSugestaoCliente({ ...item, source: "phone_contact" }))
      .filter(Boolean);
  },
  searchRecentSuggestions(query) {
    return this.rankSuggestions(carregarLista(getCustomerSuggestionStorageKey())
      .map((item) => normalizarSugestaoCliente({ ...item, source: item.source || "recent" }))
      .filter(Boolean), query);
  },
  mergeSuggestions(...listas) {
    const mapa = new Map();
    listas.flat().filter(Boolean).forEach((item) => {
      const chave = normalizarSugestaoClienteTexto(`${item.name}|${item.phone || ""}|${item.email || ""}`);
      if (!chave) return;
      const atual = mapa.get(chave);
      mapa.set(chave, atual ? {
        ...atual,
        ...item,
        usageCount: Math.max(atual.usageCount || 0, item.usageCount || 0),
        source: atual.source === "app_client" ? atual.source : item.source
      } : item);
    });
    return Array.from(mapa.values());
  },
  rankSuggestions(suggestions, query) {
    return (Array.isArray(suggestions) ? suggestions : [])
      .map((item) => ({ ...item, _score: pontuarSugestaoCliente(item, query) }))
      .filter((item) => item._score > 0)
      .sort((a, b) => b._score - a._score || normalizarSugestaoClienteTexto(a.name).localeCompare(normalizarSugestaoClienteTexto(b.name)))
      .slice(0, 8);
  },
  clearSelectedSuggestionIfUserChangesText(text) {
    if (!selectedCustomerSuggestion) return false;
    const atual = normalizarSugestaoClienteTexto(text);
    const selecionado = normalizarSugestaoClienteTexto(selectedCustomerSuggestion.name);
    if (!atual || atual === selecionado) return false;
    const phoneEl = document.getElementById("clienteTelefone");
    const emailEl = document.getElementById("clienteEmail");
    if (phoneEl && normalizarTelefoneWhatsapp(phoneEl.value) === normalizarTelefoneWhatsapp(selectedCustomerSuggestion.phone || "")) {
      phoneEl.value = "";
      clienteTelefonePedido = "";
    }
    if (emailEl && String(emailEl.value || "").trim() === String(selectedCustomerSuggestion.email || "").trim()) {
      emailEl.value = "";
      clienteEmailPedido = "";
    }
    selectedCustomerSuggestion = null;
    return true;
  },
  recordRecentSuggestion(item = {}) {
    const sugestao = normalizarSugestaoCliente({ ...item, source: item.source || "recent" });
    if (!sugestao?.name) return;
    const chaveStorage = getCustomerSuggestionStorageKey();
    const agora = new Date().toISOString();
    const lista = carregarLista(chaveStorage).map((entry) => normalizarSugestaoCliente(entry)).filter(Boolean);
    const chaveNova = normalizarSugestaoClienteTexto(`${sugestao.name}|${sugestao.phone || ""}|${sugestao.email || ""}`);
    const semDuplicado = lista.filter((entry) => normalizarSugestaoClienteTexto(`${entry.name}|${entry.phone || ""}|${entry.email || ""}`) !== chaveNova);
    semDuplicado.unshift({
      ...sugestao,
      source: sugestao.source === "phone_contact" ? "recent" : sugestao.source,
      usageCount: (sugestao.usageCount || 0) + 1,
      lastUsedAt: agora
    });
    localStorage.setItem(chaveStorage, JSON.stringify(semDuplicado.slice(0, 30)));
  }
};

function labelOrigemSugestaoCliente(source = "") {
  if (source === "phone_contact") return "Contato do telefone";
  if (source === "recent") return "Sugestão recente";
  return "Cliente cadastrado";
}

function renderCustomerSuggestions() {
  const query = String(customerSuggestionState.query || clientePedido || "").trim();
  const podeAbrirAgenda = !!getAIPlugin()?.searchPhoneContacts;
  const selectedBadge = selectedCustomerSuggestion ? `
    <span class="selected-customer-badge">${escaparHtml(labelOrigemSugestaoCliente(selectedCustomerSuggestion.source))}</span>
  ` : "";
  if (query.length < 2 && !selectedBadge && !podeAbrirAgenda) return "";
  const linhas = customerSuggestionState.suggestions.length ? customerSuggestionState.suggestions.map((item, index) => `
    <button class="customer-suggestion-item" type="button" onclick="selecionarSugestaoCliente(${index})">
      <span>
        <strong>${escaparHtml(item.name || "Contato")}</strong>
        <small>${[item.phone, item.email].filter(Boolean).map(escaparHtml).join(" • ") || "Sem telefone/e-mail"}</small>
      </span>
      <em>${escaparHtml(labelOrigemSugestaoCliente(item.source))}</em>
    </button>
  `).join("") : "";
  return `
    <div class="customer-suggestion-box">
      <div class="customer-suggestion-toolbar">
        <span id="selectedCustomerBadgeContainer">${selectedBadge}</span>
        ${podeAbrirAgenda ? `<button class="text-link" type="button" onclick="buscarSugestoesContatosTelefone()">Abrir contatos do telefone</button>` : ""}
      </div>
      ${customerSuggestionState.loading ? `<div class="customer-suggestion-loading">Buscando...</div>` : ""}
      ${linhas || (!customerSuggestionState.loading && query.length >= 2 ? `<div class="customer-suggestion-empty">Nenhum cliente encontrado. <button class="text-link" type="button" onclick="cadastrarNovoClientePedido()">Cadastrar novo</button></div>` : "")}
      ${customerSuggestionState.error ? `<div class="customer-suggestion-error">${escaparHtml(customerSuggestionState.error)}</div>` : ""}
    </div>
  `;
}

function renderizarSugestoesClientePedido() {
  const panel = document.getElementById("customerSuggestionPanel");
  if (panel) panel.innerHTML = renderCustomerSuggestions();
}

function cadastrarNovoClientePedido() {
  selectedCustomerSuggestion = null;
  customerSuggestionState.suggestions = [];
  customerSuggestionState.loading = false;
  customerSuggestionState.error = "";
  renderizarSugestoesClientePedido();
}

function fecharSugestoesClientePedido() {
  customerSuggestionState.suggestions = [];
  customerSuggestionState.loading = false;
  customerSuggestionState.error = "";
  renderizarSugestoesClientePedido();
}

async function obterTelefoneWhatsappPedido(pedido = null) {
  const campo = document.getElementById("clienteTelefone");
  const atual = campo?.value || clienteTelefonePedido || telefoneDoPedido(pedido);
  let numero = normalizarTelefoneWhatsapp(atual);
  if (!numero) {
    const digitado = await solicitarEntradaTexto({
      titulo: "WhatsApp do cliente",
      mensagem: "Informe o número com DDD ou DDI.",
      valor: "",
      tipo: "tel"
    });
    numero = normalizarTelefoneWhatsapp(digitado);
  }
  if (numero && campo) {
    campo.value = numero;
    clienteTelefonePedido = numero;
  }
  return numero;
}

function inferirTipoMaterial(nome = "") {
  const texto = removerAcentos(nome).toUpperCase();
  if (texto.includes("RESINA")) return "RESINA";
  if (texto.includes("PETG")) return "PETG";
  if (texto.includes("TPU")) return "TPU";
  return "PLA";
}

function calcularPercentualEstoque(atual = 0, base = 0) {
  const saldo = Math.max(0, Number(atual) || 0);
  const referencia = Math.max(0, Number(base) || 0);
  if (!referencia) return saldo > 0 ? 100 : 0;
  return Math.max(0, Math.min(100, Math.round((saldo / referencia) * 100)));
}

function resolverStatusEstoque(percentual = 0, material = {}) {
  const saldo = Math.max(0, Number(material.current_quantity ?? material.qtd) || 0);
  const minimo = Math.max(0, Number(material.estoqueMinimo ?? material.min_stock ?? material.minStock) || 0);
  if (minimo > 0) {
    if (saldo <= 0) return "critical";
    if (saldo <= minimo) return "low";
    return "normal";
  }
  const critical = Number(material.critical_stock_threshold ?? material.criticalStockThreshold ?? 10) || 10;
  const low = Number(material.low_stock_threshold ?? material.lowStockThreshold ?? 30) || 30;
  if (percentual <= critical) return "critical";
  if (percentual <= low) return "low";
  return "normal";
}

function labelStatusEstoque(status = "normal") {
  const mapa = { normal: "Normal", low: "Baixo", critical: "Crítico" };
  return mapa[String(status || "normal")] || "Normal";
}

function getThemePreferenceLabel(theme = appConfig.theme) {
  const preference = normalizarPreferenciaTemaInterface(theme);
  if (preference === "dark") return "Escuro";
  if (preference === "light") return "Claro";
  return "Automático";
}

function usuarioPodeVerCustosEstoque(usuario = getUsuarioAtual()) {
  return ["owner", "admin", "manager", "superadmin"].includes(getUserAccessRole(usuario));
}

function calcularCustoKgMaterialEstoque(material = {}) {
  const custoKg = Number(material.precoKg || material.preco_por_kg || material.pricePerKg || material.custoKg || material.costPerKg) || 0;
  if (custoKg > 0) return custoKg;
  const valorTotal = Number(material.valorTotal || material.valor_total || material.custoTotal || material.costTotal || material.precoPago || material.preco_pago) || 0;
  const base = Math.max(0, Number(material.quantity_base ?? material.initial_quantity ?? material.qtd) || 0);
  return valorTotal > 0 && base > 0 ? valorTotal / base : 0;
}

function normalizarLoteEstoque(lote = {}, material = {}) {
  const unidade = lote.unit || lote.unidade || material.unidade || material.unit || "g";
  const initial = Math.max(0, Number(lote.initial_quantity ?? lote.initialQuantity ?? lote.quantidadeInicial ?? lote.qtdInicial ?? lote.current_quantity ?? lote.currentQuantity ?? lote.qtd) || 0);
  const current = Math.max(0, Number(lote.current_quantity ?? lote.currentQuantity ?? lote.saldoAtual ?? lote.qtdAtual ?? lote.qtd ?? initial) || 0);
  const tipo = String(lote.batch_type || lote.batchType || lote.tipo || material.batch_control_type || "rolo").trim() || "rolo";
  const statusRaw = String(lote.status || (current <= 0 ? "esgotado" : "fechado")).trim().toLowerCase();
  const status = ["fechado", "em_uso", "esgotado", "inativo"].includes(statusRaw) ? statusRaw : "fechado";
  return {
    ...lote,
    id: lote.id || "batch-" + Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 6),
    inventory_item_id: lote.inventory_item_id || lote.inventoryItemId || material.id || "",
    batch_code: String(lote.batch_code || lote.batchCode || lote.codigo || lote.code || "").trim(),
    manufacturer_lot: String(lote.manufacturer_lot || lote.manufacturerLot || lote.loteFabricante || "").trim(),
    location_id: String(lote.location_id || lote.locationId || lote.localizacao || "").trim(),
    qr_code: String(lote.qr_code || lote.qrCode || "").trim(),
    batch_type: tipo,
    initial_quantity: initial,
    current_quantity: current,
    unit: unidade,
    cost_total: Math.max(0, Number(lote.cost_total ?? lote.costTotal ?? lote.custoTotal) || 0),
    cost_per_unit: Math.max(0, Number(lote.cost_per_unit ?? lote.costPerUnit ?? lote.custoUnitario) || 0),
    spool_tare_weight_g: Math.max(0, Number(lote.spool_tare_weight_g ?? lote.spoolTareWeightG ?? lote.taraCarretel) || 0),
    purchase_date: lote.purchase_date || lote.purchaseDate || "",
    opened_at: lote.opened_at || lote.openedAt || "",
    last_weighed_at: lote.last_weighed_at || lote.lastWeighedAt || "",
    status,
    notes: String(lote.notes || lote.observacoes || "").trim(),
    created_at: lote.created_at || lote.createdAt || new Date().toISOString(),
    updated_at: lote.updated_at || lote.updatedAt || new Date().toISOString()
  };
}

function normalizarLotesEstoque(material = {}) {
  const lotes = Array.isArray(material.inventory_batches) ? material.inventory_batches
    : Array.isArray(material.batches) ? material.batches
      : Array.isArray(material.rolos) ? material.rolos
        : [];
  return lotes.map((lote) => normalizarLoteEstoque(lote, material));
}

function materialUsaControleLote(material = {}) {
  return !!(material.is_batch_controlled || material.batch_controlled || material.controlaRolo || material.controlaLote);
}

function calcularSaldoLotesEstoque(lotes = [], unidade = "un") {
  return lotes
    .filter((lote) => !["inativo", "esgotado"].includes(String(lote.status || "").toLowerCase()))
    .filter((lote) => !lote.unit || !unidade || String(lote.unit) === String(unidade))
    .reduce((soma, lote) => soma + (Number(lote.current_quantity) || 0), 0);
}

function normalizarMaterialEstoque(material = {}) {
  const tipo = material.tipo || inferirTipoMaterial(material.nome);
  const cor = String(material.cor || "").trim();
  const nomeBase = String(material.nome || [tipo, cor].filter(Boolean).join(" ") || tipo).trim();
  const unidade = material.unit || material.unidade || "kg";
  const inventoryBatches = normalizarLotesEstoque({ ...material, nome: nomeBase, tipo, unidade });
  const isBatchControlled = materialUsaControleLote(material);
  const saldoLotes = isBatchControlled ? calcularSaldoLotesEstoque(inventoryBatches, unidade) : 0;
  const saldoAtual = isBatchControlled && inventoryBatches.length
    ? saldoLotes
    : Math.max(0, Number(material.current_quantity ?? material.currentQuantity ?? material.qtd) || 0);
  const baseInformada = Number(material.quantity_base ?? material.quantityBase ?? material.initial_quantity ?? material.initialQuantity) || 0;
  const basePadrao = String(unidade).toLowerCase() === "kg" ? Math.max(1, saldoAtual) : Math.max(1, saldoAtual);
  const base = Math.max(saldoAtual, baseInformada || basePadrao);
  const percentual = calcularPercentualEstoque(saldoAtual, base);
  const status = resolverStatusEstoque(percentual, material);
  return {
    ...material,
    id: material.id || "mat-" + Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 6),
    nome: nomeBase,
    tipo,
    cor,
    qtd: saldoAtual,
    unidade,
    unit: unidade,
    categoria: String(material.categoria || material.category || tipo || "Geral").trim(),
    tipoItem: String(material.tipoItem || material.item_type || material.itemType || (["PLA", "PETG", "TPU", "RESINA"].includes(String(tipo).toUpperCase()) ? "Item de produção 3D" : "Matéria-prima")).trim(),
    item_type: String(material.tipoItem || material.item_type || material.itemType || (["PLA", "PETG", "TPU", "RESINA"].includes(String(tipo).toUpperCase()) ? "Item de produção 3D" : "Matéria-prima")).trim(),
    estoqueMinimo: Math.max(0, Number(material.estoqueMinimo ?? material.min_stock ?? material.minStock) || 0),
    min_stock: Math.max(0, Number(material.estoqueMinimo ?? material.min_stock ?? material.minStock) || 0),
    custoUnitario: Math.max(0, Number(material.custoUnitario ?? material.unit_cost ?? material.unitCost ?? material.precoKg ?? material.custoKg) || 0),
    unit_cost: Math.max(0, Number(material.custoUnitario ?? material.unit_cost ?? material.unitCost ?? material.precoKg ?? material.custoKg) || 0),
    fornecedor: String(material.fornecedor || material.supplier || "").trim(),
    observacoes: String(material.observacoes || material.observacao || material.notes || "").trim(),
    ativo: material.ativo !== false && material.active !== false,
    is_batch_controlled: isBatchControlled,
    batch_control_type: String(material.batch_control_type || material.batchControlType || material.tipoControleLote || (isBatchControlled ? "rolo" : "")).trim(),
    inventory_batches: inventoryBatches,
    batches: inventoryBatches,
    initial_quantity: Math.max(0, Number(material.initial_quantity ?? material.initialQuantity ?? base) || 0),
    current_quantity: saldoAtual,
    quantity_base: base,
    remaining_percent: percentual,
    stock_status: status,
    low_stock_threshold: Number(material.low_stock_threshold ?? material.lowStockThreshold ?? 30) || 30,
    critical_stock_threshold: Number(material.critical_stock_threshold ?? material.criticalStockThreshold ?? 10) || 10,
    notified_low_stock: !!(material.notified_low_stock || material.notifiedLowStock),
    notified_critical_stock: !!(material.notified_critical_stock || material.notifiedCriticalStock),
    last_restock_at: material.last_restock_at || material.lastRestockAt || ""
  };
}

function normalizarEstoque() {
  let mudou = false;
  estoque = (Array.isArray(estoque) ? estoque : []).map((material) => {
    const normalizado = normalizarMaterialEstoque(material);
    if (!material.id || !material.tipo || material.qtd !== normalizado.qtd || material.quantity_base !== normalizado.quantity_base || material.remaining_percent !== normalizado.remaining_percent || material.stock_status !== normalizado.stock_status) mudou = true;
    return normalizado;
  });
  if (mudou) salvarDados();
  return estoque;
}

function getMaterialEstoque(materialId) {
  return normalizarEstoque().find((material) => String(material.id) === String(materialId)) || null;
}

function getMateriaisItem(item = {}) {
  if (Array.isArray(item.materiais) && item.materiais.length) {
    return item.materiais
      .map((material) => {
        const materialId = material.materialId || material.id || "";
        const estoqueItem = getMaterialEstoque(materialId);
        const unidade = String(material.unidade || material.unit || estoqueItem?.unidade || "kg");
        const gramasLegado = Math.max(0, Number(material.gramas) || 0);
        const quantidadeInformada = Math.max(0, Number(material.quantidade ?? material.quantity) || 0);
        const quantidade = quantidadeInformada || (unidade === "kg" ? gramasLegado / 1000 : unidade === "g" ? gramasLegado : gramasLegado);
        return {
          materialId,
          nome: material.nome || estoqueItem?.nome || "",
          quantidade,
          unidade,
          gramas: gramasLegado || (unidade === "kg" ? quantidade * 1000 : unidade === "g" ? quantidade : 0)
        };
      })
      .filter((material) => material.materialId && material.quantidade > 0);
  }

  const materialId = item.materialId || "";
  const gramas = Math.max(0, Number(item.materialGramsTotal ?? item.materialGrams) || 0);
  const estoqueItem = getMaterialEstoque(materialId);
  const unidade = String(estoqueItem?.unidade || "kg");
  const quantidade = unidade === "kg" ? gramas / 1000 : unidade === "g" ? gramas : gramas;
  return materialId && quantidade > 0 ? [{ materialId, nome: estoqueItem?.nome || "", quantidade, unidade, gramas }] : [];
}

function normalizarItemPedido(item = {}) {
  const qtd = Math.max(1, Number(item.qtd) || 1);
  const valor = Math.max(0, Number(item.valor ?? item.precoVenda) || 0);
  const materiais = getMateriaisItem(item);
  return {
    ...item,
    id: item.id || "item-" + Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 6),
    nome: String(item.nome || "Produto 3D").trim(),
    tipoImpressao: item.tipoImpressao === "RESINA" ? "RESINA" : "FDM",
    material: item.material || "",
    materiais,
    qtd,
    tempoHoras: Math.max(0, Number(item.tempoHoras ?? item.tempo) || 0),
    valor,
    total: Math.max(0, Number(item.total) || valor * qtd),
    custoMaterial: Math.max(0, Number(item.custoMaterial) || 0),
    custoEnergia: Math.max(0, Number(item.custoEnergia) || 0),
    custoTotal: Math.max(0, Number(item.custoTotal ?? item.custo) || 0),
    baseProduto: Math.max(0, Number(item.baseProduto ?? item.productBase) || 0),
    lucroProduto: Math.max(0, Number(item.lucroProduto ?? item.productProfit) || 0),
    valorProduto: Math.max(0, Number(item.valorProduto ?? item.productValue) || 0),
    taxaExtra: Math.max(0, Number(item.taxaExtra ?? item.extraFee) || 0)
  };
}

function normalizarItensPedido(pedidoOuItens = itensPedido) {
  const itens = Array.isArray(pedidoOuItens) ? pedidoOuItens : Array.isArray(pedidoOuItens?.itens) ? pedidoOuItens.itens : [];
  return itens.map(normalizarItemPedido);
}

function itemEhPlaceholderPedido(item = {}) {
  const nome = normalizarTextoBusca(item.nome || "");
  const semValor = Number(item.valor) <= 0 && Number(item.total) <= 0;
  const nomesPlaceholder = ["", "produto 3d", "novo item", "item calculado", "item do pedido"];
  return semValor && nomesPlaceholder.includes(nome);
}

function validarItemPedidoParaSalvar(item = {}) {
  const normalizado = normalizarItemPedido(item);
  const nome = String(normalizado.nome || "").trim();
  const nomeOriginal = String(item.nome || "").trim();
  const nomeBusca = normalizarTextoBusca(nome);
  const nomesPlaceholder = ["", "produto 3d", "novo item", "item calculado", "item do pedido"];
  if (!nomeOriginal || nomesPlaceholder.includes(nomeBusca) || itemEhPlaceholderPedido(normalizado)) {
    return { ok: false, reason: "Informe a descrição do item.", item: normalizado };
  }
  if ((Number(normalizado.qtd) || 0) <= 0) return { ok: false, reason: "A quantidade precisa ser maior que zero.", item: normalizado };
  if ((Number(normalizado.valor) || 0) <= 0 || (Number(normalizado.total) || 0) <= 0) return { ok: false, reason: "O valor do item precisa ser maior que zero.", item: normalizado };
  return { ok: true, item: normalizado };
}

function sanitizeItensPedidoParaSalvar(itens = itensPedido) {
  const normalizados = normalizarItensPedido(itens);
  const validos = [];
  const invalidos = [];
  normalizados.forEach((item) => {
    const validacao = validarItemPedidoParaSalvar(item);
    if (validacao.ok) validos.push(validacao.item);
    else invalidos.push({ item, reason: validacao.reason });
  });
  return { validos, invalidos };
}

function assinaturaItemPedido(item = {}) {
  const normalizado = normalizarItemPedido(item);
  const materiais = getMateriaisItem(normalizado);
  const materialPrincipal = materiais[0] || {};
  const materialId = normalizado.materialId || materialPrincipal.materialId || "";
  const material = getMaterialEstoque(materialId);
  return {
    nome: normalizarTextoBusca(normalizado.nome || ""),
    valor: Number(normalizado.valor) || 0,
    peso: Number(normalizado.materialGramsTotal ?? materialPrincipal.gramas ?? normalizado.materialGrams) || 0,
    tempoMin: Math.round((Number(normalizado.tempoHoras ?? normalizado.tempo) || 0) * 60),
    tipo: normalizarTextoBusca(normalizado.tipoImpressao || ""),
    material: normalizarTextoBusca(normalizado.material || materialPrincipal.nome || material?.nome || materialId || ""),
    cor: normalizarTextoBusca(material?.cor || normalizado.cor || ""),
    impressora: normalizarTextoBusca(normalizado.impressora || normalizado.printer || "")
  };
}

function itensPedidoEquivalentes(a = {}, b = {}) {
  const ia = assinaturaItemPedido(a);
  const ib = assinaturaItemPedido(b);
  return ia.nome === ib.nome
    && Math.abs(ia.valor - ib.valor) <= 0.01
    && Math.abs(ia.peso - ib.peso) <= 0.1
    && Math.abs(ia.tempoMin - ib.tempoMin) <= 1
    && ia.tipo === ib.tipo
    && ia.material === ib.material
    && ia.cor === ib.cor
    && ia.impressora === ib.impressora;
}

function itensPedidoSemelhantes(a = {}, b = {}) {
  const ia = assinaturaItemPedido(a);
  const ib = assinaturaItemPedido(b);
  return Math.abs(ia.valor - ib.valor) <= 0.01
    && Math.abs(ia.peso - ib.peso) <= 0.1
    && Math.abs(ia.tempoMin - ib.tempoMin) <= 1
    && (ia.nome !== ib.nome || ia.material !== ib.material);
}

function encontrarItemEquivalentePedido(item = {}) {
  return normalizarItensPedido(itensPedido).findIndex((existente) => itensPedidoEquivalentes(existente, item));
}

function encontrarItemSemelhantePedido(item = {}) {
  return normalizarItensPedido(itensPedido).findIndex((existente) => itensPedidoSemelhantes(existente, item));
}

function fingerprintItemPedido(item = {}) {
  const assinatura = assinaturaItemPedido(item);
  return JSON.stringify({
    nome: assinatura.nome,
    valor: assinatura.valor.toFixed(2),
    peso: assinatura.peso.toFixed(1),
    tempo: assinatura.tempoMin,
    tipo: assinatura.tipo,
    material: assinatura.material,
    cor: assinatura.cor,
    impressora: assinatura.impressora
  });
}

function calcularConsumoMateriais(itens = []) {
  const consumo = new Map();
  normalizarItensPedido(itens).forEach((item) => {
    getMateriaisItem(item).forEach((material) => {
      const quantidade = Math.max(0, Number(material.quantidade) || 0);
      consumo.set(material.materialId, (consumo.get(material.materialId) || 0) + quantidade);
    });
  });
  return consumo;
}

function descricaoCaixa(movimento) {
  return movimento?.descricao || movimento?.desc || "Movimento";
}

function obterDataMovimentoCaixa(movimento = {}) {
  return obterDataRegistroLocal(movimento, ["dataHora", "createdAt", "created_at", "criadoEm", "data", "date", "updatedAt", "updated_at"]);
}

function movimentoCaixaCancelado(movimento = {}) {
  return !!(movimento.cancelado || movimento.cancelled || movimento.canceladoEm || movimento.cancelled_at || String(movimento.status || "").toLowerCase() === "cancelado");
}

function getPaymentMethodsConfig() {
  const padrao = [
    { id: "dinheiro", name: "Dinheiro", type: "cash", active: true },
    { id: "pix", name: "PIX", type: "pix", active: true },
    { id: "credito", name: "Crédito", type: "credit", active: true },
    { id: "debito", name: "Débito", type: "debit", active: true }
  ];
  const origem = Array.isArray(appConfig.paymentMethods) && appConfig.paymentMethods.length ? appConfig.paymentMethods : padrao;
  return origem
    .map((metodo) => ({
      id: String(metodo.id || metodo.type || metodo.name || "").trim().toLowerCase() || "outro",
      name: String(metodo.name || metodo.nome || metodo.id || "Outro").trim(),
      type: String(metodo.type || metodo.tipo || metodo.id || "other").trim().toLowerCase(),
      active: metodo.active !== false && metodo.ativo !== false
    }));
}

function getMetodosPagamentoCaixa() {
  return getPaymentMethodsConfig().filter((metodo) => metodo.active);
}

function normalizarMetodoPagamentoCaixa(valor = "") {
  const id = String(valor || "").trim().toLowerCase();
  const metodos = getMetodosPagamentoCaixa();
  return metodos.find((metodo) => metodo.id === id || metodo.type === id) || metodos[0] || { id: "dinheiro", name: "Dinheiro", type: "cash" };
}

function getMetodoPagamentoMovimento(movimento = {}) {
  return normalizarMetodoPagamentoCaixa(movimento.payment_method_id || movimento.paymentMethodId || movimento.paymentMethod || movimento.metodoPagamento || movimento.formaPagamento || "dinheiro");
}

function caixaModoSimplesAtivo() {
  return true;
}

function getSessaoCaixaAtual() {
  const sessao = appConfig.cashSession && typeof appConfig.cashSession === "object" ? appConfig.cashSession : null;
  if (sessao && sessao.status === "open") return sessao;
  return null;
}

function abrirSessaoCaixaAutomatica(motivo = "auto") {
  if (!caixaModoSimplesAtivo()) return null;
  const aberta = getSessaoCaixaAtual();
  if (aberta) return aberta;
  const agora = new Date().toISOString();
  const sessao = {
    id: `cash-${dataLocalIso(new Date())}-${gerarHashOperacional(`${getDataOwnerId() || "local"}:${agora}`)}`,
    status: "open",
    mode: "auto",
    openedAt: agora,
    opened_at: agora,
    openingBalance: calcularTotaisCaixa().saldo,
    opening_balance: calcularTotaisCaixa().saldo,
    expectedBalance: calcularTotaisCaixa().saldo,
    expected_balance: calcularTotaisCaixa().saldo,
    reason: motivo,
    financial_flow_version: FINANCIAL_FLOW_VERSION,
    reconciliation_version: FINANCIAL_RECONCILIATION_VERSION
  };
  appConfig.cashSession = sessao;
  registrarShadowFinanceiroLocal("cash_session_auto_open", { session_id: sessao.id, motivo });
  return sessao;
}

function getIdSessaoMovimentoCaixa(movimento = {}) {
  return movimento.cash_session_id || movimento.cashSessionId || movimento.session_id || movimento.sessionId || "";
}

function calcularResumoSessaoCaixa(sessao = getSessaoCaixaAtual()) {
  const sessionId = sessao?.id || "";
  const movimentos = sessionId ? caixa.filter((movimento) => String(getIdSessaoMovimentoCaixa(movimento)) === String(sessionId)) : [];
  const resumo = movimentos.reduce((totais, movimento) => {
    if (movimentoCaixaCancelado(movimento)) {
      totais.cancelados += 1;
      return totais;
    }
    const valor = Number(movimento.valor) || 0;
    const saida = String(movimento.tipo || "").toLowerCase() === "saida";
    const metodo = getMetodoPagamentoMovimento(movimento);
    if (saida) totais.saidas += valor;
    else {
      totais.entradas += valor;
      totais.porForma[metodo.id] = (totais.porForma[metodo.id] || 0) + valor;
    }
    totais.saldo = totais.entradas - totais.saidas;
    totais.ultimaMovimentacao = obterDataMovimentoCaixa(movimento) || totais.ultimaMovimentacao;
    return totais;
  }, { entradas: 0, saidas: 0, saldo: 0, cancelados: 0, porForma: {}, ultimaMovimentacao: null });
  resumo.expectedBalance = (Number(sessao?.openingBalance ?? sessao?.opening_balance) || 0) + resumo.saldo;
  return resumo;
}

function formatarDataCurta(valor = "") {
  if (!valor) return "";
  const data = normalizarDataLocal(valor, null);
  if (!data) return String(valor);
  return data.toLocaleDateString("pt-BR");
}

function calcularSaldo() {
  return caixa.reduce((saldo, movimento) => {
    if (movimentoCaixaCancelado(movimento)) return saldo;
    const valor = Number(movimento.valor) || 0;
    return movimento.tipo === "saida" ? saldo - valor : saldo + valor;
  }, 0);
}

function calcularTotaisCaixa() {
  return caixa.reduce((totais, movimento) => {
    if (movimentoCaixaCancelado(movimento)) {
      totais.cancelados += 1;
      return totais;
    }
    const valor = Number(movimento.valor) || 0;
    if (movimento.tipo === "saida") {
      totais.saidas += valor;
    } else {
      totais.entradas += valor;
    }
    totais.saldo = totais.entradas - totais.saidas;
    return totais;
  }, { entradas: 0, saidas: 0, saldo: 0, cancelados: 0 });
}

// Regra central de planos/permissões: somente active_plan libera acesso; pending nunca ativa plano.
function getTimestampPlano(valor) {
  const timestamp = Date.parse(valor || 0);
  return Number.isFinite(timestamp) ? timestamp : 0;
}

function getRemainingDays(expiresAt, now = Date.now()) {
  const fim = getTimestampPlano(expiresAt);
  if (!fim) return 0;
  return Math.max(0, Math.ceil((fim - now) / (24 * 60 * 60 * 1000)));
}

function calcularFimTrial(inicio, dias = billingConfig.trialDays) {
  const dataInicio = getTimestampPlano(inicio);
  if (!dataInicio) return "";
  return new Date(dataInicio + Math.max(1, Number(dias) || 7) * 24 * 60 * 60 * 1000).toISOString();
}

function normalizarStatusLicencaEfetiva(status = "FREE") {
  const valor = String(status || "FREE").toUpperCase().trim();
  const mapa = {
    ACTIVE: PLAN_ACCESS_STATES.ACTIVE,
    ATIVO: PLAN_ACCESS_STATES.ACTIVE,
    PAID: PLAN_ACCESS_STATES.ACTIVE,
    PAGO: PLAN_ACCESS_STATES.ACTIVE,
    TRIAL: PLAN_ACCESS_STATES.TRIAL,
    TESTE: PLAN_ACCESS_STATES.TRIAL,
    PENDING: PLAN_ACCESS_STATES.PENDING,
    PENDENTE: PLAN_ACCESS_STATES.PENDING,
    EXPIRED: PLAN_ACCESS_STATES.EXPIRED,
    VENCIDO: PLAN_ACCESS_STATES.EXPIRED,
    BLOCKED: PLAN_ACCESS_STATES.BLOCKED,
    BLOQUEADO: PLAN_ACCESS_STATES.BLOCKED,
    FREE: PLAN_ACCESS_STATES.FREE,
    GRATIS: PLAN_ACCESS_STATES.FREE,
    GRATUITO: PLAN_ACCESS_STATES.FREE
  };
  return mapa[valor] || PLAN_ACCESS_STATES.FREE;
}

function slugPlanoPorLicencaEfetiva(licenca = {}) {
  const status = normalizarStatusLicencaEfetiva(licenca.effective_status || licenca.effectiveStatus);
  const planCode = String(licenca.plan_code || licenca.planCode || "").toUpperCase().trim();
  if (status === PLAN_ACCESS_STATES.TRIAL) return "premium_trial";
  if (status === PLAN_ACCESS_STATES.ACTIVE || ["START", "PRO", "PREMIUM"].includes(planCode)) {
    if (status === PLAN_ACCESS_STATES.FREE) return "free";
    if (planCode === "START") return "start";
    return "pro";
  }
  return "free";
}

function statusLegadoPorLicencaEfetiva(status) {
  const normalizado = normalizarStatusLicencaEfetiva(status);
  if (normalizado === PLAN_ACCESS_STATES.TRIAL) return "trialing";
  if (normalizado === PLAN_ACCESS_STATES.ACTIVE) return "active";
  if (normalizado === PLAN_ACCESS_STATES.PENDING) return "pending";
  if (normalizado === PLAN_ACCESS_STATES.BLOCKED) return "blocked";
  if (normalizado === PLAN_ACCESS_STATES.EXPIRED) return "expired";
  return "active";
}

function getLicencaEfetivaSnapshotLocal() {
  const status = billingConfig.effectiveStatus || billingConfig.effective_status || "";
  if (!status) return null;
  const updatedAt = billingConfig.effectiveLicenseUpdatedAt || billingConfig.effectiveUpdatedAt || "";
  const stale = billingConfig.effectiveLicenseStale === true;
  return {
    userId: billingConfig.effectiveUserId || syncConfig.supabaseUserId || "",
    clientId: billingConfig.clientId || "",
    planCode: billingConfig.effectivePlanCode || "",
    effectiveStatus: normalizarStatusLicencaEfetiva(status),
    isPremium: billingConfig.effectiveIsPremium === true,
    isTrial: billingConfig.effectiveIsTrial === true,
    isPending: billingConfig.effectiveIsPending === true,
    isBlocked: billingConfig.effectiveIsBlocked === true,
    remainingTrialDays: Math.max(0, Number(billingConfig.effectiveRemainingTrialDays || 0) || 0),
    trialStartAt: billingConfig.trialStartedAt || "",
    trialEndAt: billingConfig.trialExpiresAt || "",
    trialConsumedAt: billingConfig.trialConsumedAt || "",
    premiumUntil: billingConfig.premiumUntil || billingConfig.planExpiresAt || "",
    blockedAt: billingConfig.blockedAt || "",
    blockedReason: billingConfig.blockedReason || "",
    source: stale ? "backend-rpc-cache-stale" : (billingConfig.effectiveLicenseSource || "backend-rpc"),
    updatedAt,
    stale
  };
}

function licencaEfetivaRemotaFresca() {
  const snapshot = getLicencaEfetivaSnapshotLocal();
  return !!snapshot && snapshot.stale !== true && ["backend-rpc", "backend-rpc-legacy", "subscriptions", "superadmin"].includes(String(snapshot.source || ""));
}

function montarSnapshotPlanoDeLicencaEfetiva(licenca = getLicencaEfetivaSnapshotLocal(), source = "backend-rpc") {
  if (!licenca) return null;
  const state = normalizarStatusLicencaEfetiva(licenca.effectiveStatus || licenca.effective_status);
  const planCode = String(licenca.planCode || licenca.plan_code || "").toUpperCase().trim();
  const activePlan = state === PLAN_ACCESS_STATES.TRIAL
    ? "premium_trial"
    : state === PLAN_ACCESS_STATES.ACTIVE
      ? (planCode === "START" ? "start" : "pro")
      : "free";
  const trialRemainingDays = Math.max(0, Number(licenca.remainingTrialDays || licenca.remaining_trial_days || 0) || 0);
  const planExpiresAt = licenca.premiumUntil || licenca.premium_until || licenca.expires_at || "";
  return {
    state,
    source: source || licenca.source || "backend-rpc",
    activePlan,
    pendingPlan: licenca.isPending || licenca.is_pending ? (activePlan === "free" ? "premium" : "") : "",
    paymentStatus: licenca.isPending || licenca.is_pending ? "pending" : "none",
    subscriptionStatus: state === PLAN_ACCESS_STATES.TRIAL ? "trialing" : state === PLAN_ACCESS_STATES.ACTIVE ? "active" : "free",
    statusPlano: statusLegadoPorLicencaEfetiva(state),
    pending: state === PLAN_ACCESS_STATES.PENDING || licenca.isPending === true || licenca.is_pending === true,
    pendingExpired: false,
    trialStartedAt: licenca.trialStartAt || licenca.trial_start_at || licenca.trial_started_at || "",
    trialExpiresAt: licenca.trialEndAt || licenca.trial_end_at || licenca.trial_expires_at || "",
    trialRemainingDays,
    planExpiresAt,
    planRemainingDays: planExpiresAt ? getRemainingDays(planExpiresAt) : 0,
    hasPremium: state === PLAN_ACCESS_STATES.TRIAL || state === PLAN_ACCESS_STATES.ACTIVE,
    isTrialActive: state === PLAN_ACCESS_STATES.TRIAL,
    isPaidActive: state === PLAN_ACCESS_STATES.ACTIVE,
    adsAllowed: state === PLAN_ACCESS_STATES.FREE || state === PLAN_ACCESS_STATES.PENDING,
    blockLevel: state === PLAN_ACCESS_STATES.BLOCKED ? "total" : "none",
    stale: licenca.stale === true
  };
}

function primeiroValorPlano(...valores) {
  for (const valor of valores) {
    if (valor === null || valor === undefined) continue;
    const texto = String(valor).trim();
    if (texto) return valor;
  }
  return "";
}

function getTrialSnapshotPlano(source = {}, now = Date.now()) {
  const startedAt = primeiroValorPlano(source.trialStartedAt, source.trial_started_at, source.trialStartAt, source.trial_start_at);
  const expiresAt = primeiroValorPlano(
    source.trialExpiresAt,
    source.trial_expires_at,
    source.trialEndAt,
    source.trial_end_at,
    startedAt ? calcularFimTrial(startedAt, source.trialDays || source.trial_days || billingConfig.trialDays || DEFAULT_TRIAL_DAYS) : ""
  );
  const expiresMs = getTimestampPlano(expiresAt);
  return {
    startedAt: startedAt || "",
    expiresAt: expiresAt || "",
    expiresMs,
    remainingDays: expiresMs ? getRemainingDays(expiresAt, now) : 0,
    active: !!expiresMs && expiresMs > now
  };
}

function resolverEstadoPlano(user = getUsuarioAtual(), options = {}) {
  try {
    limparCheckoutsLocaisExpirados();
  } catch (_) {}
  const now = Number(options.now || Date.now());
  const assinatura = options.subscription === undefined
    ? getAssinaturaSaas(user?.clientId || billingConfig.clientId || "")
    : options.subscription;
  const cliente = options.client === undefined ? getClienteSaasAtual() : options.client;
  const source = options.source || (assinatura ? "supabase/local-subscription" : "local-cache");

  if (isSuperAdmin(user)) {
    const snapshotSuper = {
      state: PLAN_ACCESS_STATES.ACTIVE,
      source,
      activePlan: "pro",
      pendingPlan: "",
      paymentStatus: "none",
      subscriptionStatus: "active",
      statusPlano: "active",
      pending: false,
      pendingExpired: false,
      trialStartedAt: "",
      trialExpiresAt: "",
      trialRemainingDays: 0,
      planExpiresAt: "",
      planRemainingDays: 9999,
      hasPremium: true,
      isTrialActive: false,
      isPaidActive: true,
      adsAllowed: false,
      blockLevel: "none"
    };
    logEstadoPlanoDebug(snapshotSuper);
    return snapshotSuper;
  }

  if (options.ignoreEffectiveLicense !== true) {
    const licencaEfetiva = getLicencaEfetivaSnapshotLocal();
    const clientIdUsuario = String(user?.clientId || billingConfig.clientId || "");
    const clientIdLicenca = String(licencaEfetiva?.clientId || "");
    if (licencaEfetiva && (!clientIdUsuario || !clientIdLicenca || clientIdUsuario === clientIdLicenca)) {
      const snapshotEfetivo = montarSnapshotPlanoDeLicencaEfetiva(licencaEfetiva, licencaEfetiva.source || source);
      if (snapshotEfetivo) {
        logEstadoPlanoDebug(snapshotEfetivo);
        return snapshotEfetivo;
      }
    }
  }

  const activePlan = normalizarSlugPlano(primeiroValorPlano(
    assinatura?.activePlan,
    assinatura?.active_plan,
    cliente?.activePlan,
    cliente?.active_plan,
    billingConfig.activePlan,
    user?.activePlan,
    user?.active_plan,
    assinatura?.planSlug,
    assinatura?.plan_slug,
    assinatura?.planId,
    assinatura?.plan_id,
    cliente?.planoAtual,
    cliente?.plano_atual,
    billingConfig.planSlug,
    user?.planSlug,
    user?.plan_slug,
    user?.planoAtual,
    "free"
  ));
  const pendingPlan = normalizarSlugPlano(primeiroValorPlano(
    assinatura?.pendingPlan,
    assinatura?.pending_plan,
    cliente?.pendingPlan,
    cliente?.pending_plan,
    billingConfig.pendingPlan,
    user?.pendingPlan,
    user?.pending_plan,
    ""
  ));
  const paymentStatus = normalizarStatusPagamento(primeiroValorPlano(
    assinatura?.paymentStatus,
    assinatura?.payment_status,
    cliente?.paymentStatus,
    cliente?.payment_status,
    billingConfig.paymentStatus,
    user?.paymentStatus,
    user?.payment_status,
    "none"
  ));
  const subscriptionStatus = normalizarStatusAssinaturaDefinitivo(primeiroValorPlano(
    assinatura?.subscriptionStatus,
    assinatura?.subscription_status,
    cliente?.subscriptionStatus,
    cliente?.subscription_status,
    billingConfig.subscriptionStatus,
    user?.subscriptionStatus,
    user?.subscription_status,
    activePlan === "premium_trial" ? "trialing" : isPlanoPagoSlug(activePlan) ? "active" : "free"
  ));
  const statusPlanoBruto = primeiroValorPlano(
    assinatura?.status,
    assinatura?.statusAssinatura,
    assinatura?.status_assinatura,
    cliente?.statusAssinatura,
    cliente?.status_assinatura,
    billingConfig.licenseStatus,
    user?.planStatus,
    activePlan === "premium_trial" ? "trialing" : isPlanoPagoSlug(activePlan) ? "active" : "active"
  );
  const statusPlano = ["free", "gratis", "grátis"].includes(String(statusPlanoBruto || "").toLowerCase().trim())
    ? "active"
    : normalizarStatusPlano(statusPlanoBruto);
  const trial = getTrialSnapshotPlano({
    trialStartedAt: primeiroValorPlano(assinatura?.trialStartedAt, assinatura?.trial_started_at, cliente?.trialStartedAt, cliente?.trial_started_at, billingConfig.trialStartedAt, user?.trialStartedAt, user?.trial_started_at),
    trialExpiresAt: primeiroValorPlano(assinatura?.trialExpiresAt, assinatura?.trial_expires_at, cliente?.trialExpiresAt, cliente?.trial_expires_at, billingConfig.trialExpiresAt, user?.trialExpiresAt, user?.trial_expires_at),
    trialDays: primeiroValorPlano(assinatura?.trialDays, assinatura?.trial_days, cliente?.trialDays, cliente?.trial_days, billingConfig.trialDays, user?.trialDays, user?.trial_days, DEFAULT_TRIAL_DAYS)
  }, now);
  const planExpiresAt = primeiroValorPlano(
    assinatura?.planExpiresAt,
    assinatura?.plan_expires_at,
    assinatura?.currentPeriodEnd,
    assinatura?.current_period_end,
    assinatura?.expiresAt,
    assinatura?.expires_at,
    assinatura?.nextBillingAt,
    assinatura?.next_billing_at,
    cliente?.planExpiresAt,
    cliente?.plan_expires_at,
    billingConfig.planExpiresAt,
    billingConfig.paidUntil,
    user?.planExpiresAt,
    user?.plan_expires_at
  );
  const planExpiresMs = getTimestampPlano(planExpiresAt);
  const planExpired = !!planExpiresMs && planExpiresMs <= now;
  const pendingStartedAt = primeiroValorPlano(assinatura?.pendingStartedAt, assinatura?.pending_started_at, billingConfig.pendingStartedAt, cliente?.pendingStartedAt, cliente?.pending_started_at);
  const pendingExpired = paymentStatus === "pending" && (!pendingStartedAt || (now - getTimestampPlano(pendingStartedAt) > LOCAL_CHECKOUT_PENDING_TTL_MS));
  const pending = !pendingExpired && (paymentStatus === "pending" || (!!pendingPlan && pendingPlan !== "free") || statusPlano === "pending");
  const cancelAtPeriodEnd = normalizarBooleanoPlano(primeiroValorPlano(
    assinatura?.cancelAtPeriodEnd,
    assinatura?.cancel_at_period_end,
    cliente?.cancelAtPeriodEnd,
    cliente?.cancel_at_period_end,
    billingConfig.cancelAtPeriodEnd,
    user?.cancelAtPeriodEnd,
    user?.cancel_at_period_end,
    false
  ));
  const blocked = usuarioEstaBloqueado(user) || (paymentStatus !== "pending" && (billingConfig.licenseStatus === "blocked" || billingConfig.licenseBlockLevel === "total" || billingConfig.blocked));
  const paidActive = ["start", "pro"].includes(activePlan)
    && !planExpired
    && (["active", "canceling"].includes(subscriptionStatus) || ["active", "canceling"].includes(statusPlano) || paymentStatus === "approved" || cancelAtPeriodEnd);
  const trialActive = trial.active && (
    activePlan === "premium_trial"
    || billingConfig.isTrialActive === true
    || assinatura?.isTrialActive === true
    || cliente?.isTrialActive === true
  );

  let state = PLAN_ACCESS_STATES.FREE;
  if (blocked) {
    state = PLAN_ACCESS_STATES.BLOCKED;
  } else if (paidActive) {
    state = PLAN_ACCESS_STATES.ACTIVE;
  } else if (trialActive) {
    state = PLAN_ACCESS_STATES.TRIAL;
  } else if (pending) {
    state = PLAN_ACCESS_STATES.PENDING;
  } else if (
    ["past_due", "cancelled", "expired"].includes(subscriptionStatus)
    || ["past_due", "cancelled", "expired"].includes(statusPlano)
    || (activePlan === "premium_trial" && !!trial.expiresMs && !trial.active)
    || (["start", "pro"].includes(activePlan) && planExpired)
  ) {
    state = PLAN_ACCESS_STATES.EXPIRED;
  }

  const planoEfetivoUnico = state === PLAN_ACCESS_STATES.TRIAL
    ? "premium_trial"
    : state === PLAN_ACCESS_STATES.ACTIVE
      ? activePlan
      : "free";
  const snapshot = {
    state,
    source,
    activePlan: planoEfetivoUnico,
    pendingPlan: pendingPlan === "free" ? "" : pendingPlan,
    paymentStatus,
    subscriptionStatus,
    statusPlano,
    cancelAtPeriodEnd,
    pending,
    pendingExpired: !!pendingExpired,
    trialStartedAt: trial.startedAt,
    trialExpiresAt: trial.expiresAt,
    trialRemainingDays: trial.remainingDays,
    planExpiresAt: planExpiresAt || "",
    planRemainingDays: planExpiresAt ? getRemainingDays(planExpiresAt, now) : 0,
    hasPremium: [PLAN_ACCESS_STATES.TRIAL, PLAN_ACCESS_STATES.ACTIVE].includes(state),
    isTrialActive: state === PLAN_ACCESS_STATES.TRIAL,
    isPaidActive: state === PLAN_ACCESS_STATES.ACTIVE,
    adsAllowed: [PLAN_ACCESS_STATES.FREE, PLAN_ACCESS_STATES.PENDING, PLAN_ACCESS_STATES.EXPIRED].includes(state),
    blockLevel: state === PLAN_ACCESS_STATES.BLOCKED ? "total" : "none"
  };
  logEstadoPlanoDebug(snapshot);
  return snapshot;
}

function temPagamentoPendenteReal(clientId = getClientIdAtual(), assinatura = getAssinaturaSaas(clientId)) {
  const assinaturaId = String(assinatura?.id || billingConfig.subscriptionId || "");
  return saasPayments.some((pagamento) => {
    const status = String(pagamento.status || "").toLowerCase().trim();
    if (status !== "pending") return false;
    const mesmoCliente = !clientId || String(pagamento.clientId || "") === String(clientId);
    const mesmaAssinatura = !assinaturaId || !pagamento.subscriptionId || String(pagamento.subscriptionId) === assinaturaId;
    const transacaoReal = temTransacaoMercadoPagoReal(pagamento);
    return mesmoCliente && mesmaAssinatura && transacaoReal;
  });
}

function getPlanAccessState(userSubscription = getAssinaturaSaas(), options = {}) {
  const usuario = options.user === undefined ? getUsuarioAtual() : options.user;
  const cliente = options.client === undefined ? getClienteSaasAtual() : options.client;
  const assinatura = userSubscription ? normalizarAssinaturaSaas(userSubscription) : null;
  const estado = resolverEstadoPlano(usuario, {
    subscription: assinatura,
    client: cliente,
    source: options.source || "plan-access-state",
    now: options.now
  });
  const currentPlan = normalizarSlugPlano(primeiroValorPlano(
    assinatura?.activePlan,
    assinatura?.planSlug,
    cliente?.activePlan,
    cliente?.planoAtual,
    billingConfig.activePlan,
    billingConfig.planSlug,
    "free"
  ));
  const effectivePlan = normalizarSlugPlano(estado.hasPremium ? estado.activePlan : "free");
  const accessEndsAt = primeiroValorPlano(
    estado.planExpiresAt,
    assinatura?.currentPeriodEnd,
    assinatura?.expiresAt,
    assinatura?.nextBillingAt,
    cliente?.currentPeriodEnd,
    cliente?.planExpiresAt,
    billingConfig.currentPeriodEnd,
    billingConfig.planExpiresAt,
    billingConfig.paidUntil,
    ""
  );
  const cancelAtPeriodEnd = normalizarBooleanoPlano(primeiroValorPlano(
    assinatura?.cancelAtPeriodEnd,
    cliente?.cancelAtPeriodEnd,
    billingConfig.cancelAtPeriodEnd,
    false
  ));
  const isPaid = ["start", "pro"].includes(effectivePlan);
  const isActive = estado.state === PLAN_ACCESS_STATES.ACTIVE || estado.state === PLAN_ACCESS_STATES.TRIAL;
  const isCancelingAtPeriodEnd = isPaid && isActive && cancelAtPeriodEnd;
  const realPendingPayment = temPagamentoPendenteReal(assinatura?.clientId || cliente?.id || billingConfig.clientId, assinatura);
  const upgradeOptions = getPlanUpgradeOptions(effectivePlan);
  return {
    currentPlan,
    effectivePlan,
    subscriptionStatus: isCancelingAtPeriodEnd ? "canceling" : estado.subscriptionStatus,
    paymentStatus: estado.paymentStatus,
    isFree: !isPaid,
    isPaid,
    isActive,
    isCancelingAtPeriodEnd,
    canUpgrade: upgradeOptions.length > 0,
    upgradeOptions,
    canCancelRenewal: isPaid && isActive && !isCancelingAtPeriodEnd,
    canReactivateRenewal: isCancelingAtPeriodEnd,
    canSubscribe: effectivePlan === "free",
    shouldShowPendingPayment: estado.pending === true && realPendingPayment,
    accessEndsAt: accessEndsAt || "",
    state: estado.state,
    pendingCheckout: estado.pending === true && !realPendingPayment,
    planRemainingDays: estado.planRemainingDays || 0
  };
}

function getStorefrontPublicationAccess(usuario = getUsuarioAtual(), options = {}) {
  if (isSuperAdmin(usuario)) {
    return {
      canEdit: true,
      canPublish: true,
      canShare: true,
      effectivePlan: "pro",
      status: STOREFRONT_PUBLICATION_STATUS.PUBLISHED,
      reason: "superadmin",
      publicMessage: "",
      internalMessage: "Superadmin pode publicar e revisar lojas.",
      accessEndsAt: ""
    };
  }
  const accessState = getPlanAccessState(options.subscription === undefined ? getAssinaturaSaas(usuario?.clientId || billingConfig.clientId || "") : options.subscription, {
    user: usuario,
    client: options.client,
    source: options.source || "storefront-publication-access",
    now: options.now
  });
  const effectivePlan = normalizarSlugPlano(accessState.effectivePlan || "free");
  const paidPlan = ["start", "pro"].includes(effectivePlan);
  const paidActive = paidPlan && accessState.isActive === true;
  const paymentInactive = [PLAN_ACCESS_STATES.EXPIRED, PLAN_ACCESS_STATES.BLOCKED].includes(accessState.state);
  const canPublish = paidActive;
  const status = canPublish
    ? STOREFRONT_PUBLICATION_STATUS.PUBLISHED
    : paymentInactive
      ? STOREFRONT_PUBLICATION_STATUS.SUSPENDED_PAYMENT
      : STOREFRONT_PUBLICATION_STATUS.SUSPENDED_PLAN;
  const accessEndsAt = accessState.accessEndsAt || "";
  const cancelingMessage = accessState.isCancelingAtPeriodEnd && accessEndsAt
    ? `Sua loja ficará publicada até ${new Date(accessEndsAt).toLocaleDateString("pt-BR")}.`
    : "";
  return {
    canEdit: !!usuario,
    canPublish,
    canShare: canPublish,
    effectivePlan,
    status,
    reason: canPublish ? (accessState.isCancelingAtPeriodEnd ? "canceling_period_active" : "paid_active") : (paymentInactive ? "subscription_inactive" : "plan_required"),
    publicMessage: "Loja temporariamente indisponível.",
    internalMessage: canPublish
      ? (cancelingMessage || "Sua loja pode ser publicada nos planos Start e Pro ativos.")
      : paymentInactive
        ? "Sua loja está desativada porque a assinatura não está ativa."
        : "Sua loja está salva, mas a publicação pública está disponível apenas nos planos Start e Pro.",
    accessEndsAt,
    accessState
  };
}

function getStorefrontPublicationStatus(store = {}, access = getStorefrontPublicationAccess()) {
  const raw = String(store.publication_status || store.publicationStatus || store.status || "").toLowerCase().trim();
  if (raw === STOREFRONT_PUBLICATION_STATUS.PUBLISHED && store.active !== true) return STOREFRONT_PUBLICATION_STATUS.UNPUBLISHED;
  if (store.active === true && access.canPublish) return STOREFRONT_PUBLICATION_STATUS.PUBLISHED;
  if (store.active === true && !access.canPublish) return access.status;
  if (Object.values(STOREFRONT_PUBLICATION_STATUS).includes(raw)) return raw;
  return STOREFRONT_PUBLICATION_STATUS.DRAFT;
}

function isStorefrontPubliclyAccessible(store = {}, access = getStorefrontPublicationAccess()) {
  const status = getStorefrontPublicationStatus(store, access);
  return store?.active === true
    && access.canPublish === true
    && status === STOREFRONT_PUBLICATION_STATUS.PUBLISHED;
}

function isStorefrontRemotePubliclyAccessible(store = {}) {
  const status = String(store.publication_status || store.publicationStatus || store.status || "").toLowerCase().trim();
  return store?.active === true
    && status === STOREFRONT_PUBLICATION_STATUS.PUBLISHED;
}

function logEstadoPlanoDebug(snapshot = {}) {
  if (!PLAN_DEBUG_ENABLED || typeof console === "undefined") return;
  const holder = typeof window !== "undefined" ? window : globalThis;
  const chave = [
    snapshot.state,
    snapshot.activePlan,
    snapshot.pendingPlan,
    snapshot.paymentStatus,
    snapshot.subscriptionStatus,
    snapshot.trialExpiresAt,
    snapshot.planExpiresAt,
    snapshot.source
  ].join("|");
  if (holder.__simplificaLastPlanDebug === chave) return;
  holder.__simplificaLastPlanDebug = chave;
  debugInfo("[Simplifica3D][PlanState]", {
    state: snapshot.state,
    source: snapshot.source,
    active_plan: snapshot.activePlan,
    pending_plan: snapshot.pendingPlan || "",
    payment_status: snapshot.paymentStatus,
    subscription_status: snapshot.subscriptionStatus,
    trial_start_at: snapshot.trialStartedAt || "",
    trial_end_at: snapshot.trialExpiresAt || "",
    remaining_days: snapshot.trialRemainingDays || snapshot.planRemainingDays || 0,
    pending: snapshot.pending === true,
    active: snapshot.hasPremium === true
  });
}

function usuarioEstaBloqueado(user = getUsuarioAtual()) {
  const status = String(user?.planStatus || "").toLowerCase();
  return !!user?.bloqueado || user?.ativo === false || status === "blocked" || status === "bloqueado";
}

function licencaEfetivaBloqueada(user = getUsuarioAtual()) {
  if (isSuperAdmin(user)) return false;
  return usuarioEstaBloqueado(user)
    || billingConfig.effectiveIsBlocked === true
    || billingConfig.effectiveStatus === PLAN_ACCESS_STATES.BLOCKED
    || billingConfig.licenseStatus === "blocked"
    || billingConfig.licenseBlockLevel === "total"
    || billingConfig.blocked === true;
}

function planoGlobalBloqueado() {
  if (billingConfig.paymentStatus === "pending") return false;
  if (normalizarSlugPlano(billingConfig.activePlan || billingConfig.planSlug) === "free") return false;
  return billingConfig.licenseStatus === "blocked" || billingConfig.licenseBlockLevel === "total" || billingConfig.blocked;
}

function isTrialActive(user = getUsuarioAtual()) {
  return resolverEstadoPlano(user, { source: "isTrialActive" }).isTrialActive;
}

function hasPremiumAccess(subscription = getAssinaturaSaas()) {
  if (!subscription) return false;
  return resolverEstadoPlano(getUsuarioAtual(), { subscription, source: "hasPremiumAccess" }).hasPremium;
}

function hasActivePlan(user = getUsuarioAtual()) {
  if (isSuperAdmin(user)) return true;
  return resolverEstadoPlano(user, { source: "hasActivePlan" }).hasPremium;
}

function canUsePremiumFeatures(user = getUsuarioAtual()) {
  if (!hasActivePlan(user)) return false;
  if (isSuperAdmin(user)) return true;
  return dispositivoDentroDoLimite(user?.email || getEmailLicencaAtual());
}

function getPlanoAtual(user = getUsuarioAtual()) {
  if (isSuperAdmin(user)) {
    return {
      nome: "Super Admin",
      status: "superadmin",
      slug: "pro",
      completo: true,
      diasRestantes: 9999,
      descricao: "Pro interno"
    };
  }

  const estadoPlano = resolverEstadoPlano(user, { source: "getPlanoAtual" });
  if (estadoPlano.state === PLAN_ACCESS_STATES.BLOCKED) {
    return {
      nome: "Bloqueado",
      status: "bloqueado",
      slug: estadoPlano.activePlan || "free",
      completo: false,
      diasRestantes: 0,
      descricao: "Acesso bloqueado pelo administrador"
    };
  }

  const planoSaas = getPlanoSaas(estadoPlano.activePlan || "free");
  const descricoes = {
    [PLAN_ACCESS_STATES.TRIAL]: `${estadoPlano.trialRemainingDays || DEFAULT_TRIAL_DAYS} dia(s) restantes de acesso Pro`,
    [PLAN_ACCESS_STATES.ACTIVE]: estadoPlano.planRemainingDays ? `${estadoPlano.planRemainingDays} dia(s) restantes no plano pago` : "Assinatura paga ativa",
    [PLAN_ACCESS_STATES.PENDING]: "Pagamento pendente. Seu plano atual continua funcionando e o pending não bloqueia o app.",
    [PLAN_ACCESS_STATES.EXPIRED]: "Plano vencido. O app voltou para o Free com anúncios.",
    [PLAN_ACCESS_STATES.FREE]: "Plano Free com anúncios"
  };
  const nomes = {
    [PLAN_ACCESS_STATES.TRIAL]: "Pro",
    [PLAN_ACCESS_STATES.ACTIVE]: planoSaas.slug === "start" ? "Start" : "Pro",
    [PLAN_ACCESS_STATES.PENDING]: "Pendente",
    [PLAN_ACCESS_STATES.EXPIRED]: "Expirado",
    [PLAN_ACCESS_STATES.FREE]: "Free"
  };
  const statusUi = {
    [PLAN_ACCESS_STATES.TRIAL]: "pago",
    [PLAN_ACCESS_STATES.ACTIVE]: "pago",
    [PLAN_ACCESS_STATES.PENDING]: "pendente",
    [PLAN_ACCESS_STATES.EXPIRED]: "expirado",
    [PLAN_ACCESS_STATES.FREE]: "gratis"
  };
  return {
    nome: nomes[estadoPlano.state] || "Free",
    status: statusUi[estadoPlano.state] || "gratis",
    slug: planoSaas.slug,
    completo: estadoPlano.hasPremium,
    blockLevel: estadoPlano.blockLevel,
    diasRestantes: estadoPlano.state === PLAN_ACCESS_STATES.TRIAL
      ? estadoPlano.trialRemainingDays
      : estadoPlano.state === PLAN_ACCESS_STATES.ACTIVE
        ? (estadoPlano.planRemainingDays || 9999)
        : 0,
    descricao: descricoes[estadoPlano.state] || "Plano Free com anúncios",
    plano: planoSaas,
    state: estadoPlano.state,
    pending: estadoPlano.pending,
    source: estadoPlano.source
  };
}

function temAcessoCompleto() {
  return canUsePremiumFeatures();
}

function temPlanoProPagoAtivo(user = getUsuarioAtual()) {
  if (!user || licencaEfetivaBloqueada(user)) return false;

  const licenca = getLicencaEfetivaSnapshotLocal();
  if (licenca && licenca.stale !== true) {
    const status = normalizarStatusLicencaEfetiva(licenca.effectiveStatus || licenca.effective_status);
    const planCode = String(licenca.planCode || licenca.plan_code || "").toUpperCase().trim();
    const planoPro = !planCode || ["PREMIUM", "PRO"].includes(planCode);
    return status === PLAN_ACCESS_STATES.ACTIVE
      && planoPro
      && licenca.isTrial !== true
      && licenca.isBlocked !== true;
  }

  // IA offline e um beneficio pago: Superadmin, Trial e Free nao entram por atalho local.
  if (isSuperAdmin(user)) return false;

  const estadoPlano = resolverEstadoPlano(user, { source: "temPlanoProPagoAtivo", ignoreEffectiveLicense: true });
  return estadoPlano.state === PLAN_ACCESS_STATES.ACTIVE
    && estadoPlano.isPaidActive === true
    && estadoPlano.isTrialActive !== true
    && normalizarSlugPlano(estadoPlano.activePlan || "") === "pro";
}

function exigirPlanoCompleto() {
  return PlanService.exigirPlanoCompleto();
}

function permitirAcaoPlanoCompleto() {
  const resultado = exigirPlanoCompleto();
  if (resultado.allowed) return true;
  mostrarBloqueioPlano(resultado);
  return false;
}

function permitirAcaoBasicaFree(mensagem = "Seu acesso está bloqueado. Regularize o plano para continuar.") {
  const plano = getPlanoAtual();
  if (plano.blockLevel === "total" || plano.status === "bloqueado") {
    mostrarBloqueioPlano({ message: mensagem });
    return false;
  }
  return true;
}

function permitirVisualizacaoOperacionalBasica() {
  const plano = getPlanoAtual();
  return !(plano.blockLevel === "total" || plano.status === "bloqueado");
}

function mostrarBloqueioPlano(resultado) {
  const mensagem = resultado?.message || "Recurso premium. O trial ativo e o plano pago liberam esta função.";
  if (resultado?.reason === "DEVICE_LIMIT") {
    alert(mensagem);
  } else {
    mostrarModalLimitePlano(mensagem);
  }
  trocarTela("assinatura");
}

function mostrarModalLimitePlano(mensagem = "Você atingiu o limite do seu plano. Faça upgrade para continuar.") {
  const popup = document.getElementById("popup");
  if (!popup) {
    alert(mensagem);
    return;
  }
  popup.innerHTML = `
    <div class="modal-backdrop" role="dialog" aria-modal="true" data-action="plan-modal-close">
      <div class="modal-card limit-modal">
        <div class="modal-header">
          <h2>Você atingiu o limite do seu plano</h2>
          <button class="icon-button" type="button" data-action="plan-modal-close" title="Fechar">✕</button>
        </div>
        <p class="muted">${escaparHtml(mensagem)}</p>
        <div class="actions">
          <button class="btn secondary" type="button" data-action="plan-upgrade">Ver planos</button>
          <button class="btn" type="button" data-action="plan-upgrade">Fazer upgrade</button>
        </div>
      </div>
    </div>
  `;
  promoverPopupParaDialogUiV3(popup, { title: "Limite do plano" });
  registrarAuditoria("tentativa", { motivo: "limite_plano", mensagem });
}

