function trocarAbaAuth(tab) {
  window.__authTab = tab === "signup" ? "signup" : "signin";
  renderApp();
  setTimeout(() => {
    const alvo = window.__authTab === "signup" ? "signupNome" : "usuarioLoginEmail";
    document.getElementById(alvo)?.focus();
  }, 0);
}

