function renderAssinatura() {
  verificarVencimentoPlanoLocal(false);
  const usuario = getUsuarioAtual();
  const accessState = getPlanAccessState(getAssinaturaSaas(usuario?.clientId || billingConfig.clientId || ""), { user: usuario, source: "plans-screen" });
  const superadmin = isSuperAdmin();
  const isPremiumAtivo = superadmin || accessState.isPaid;
  const planoAtual = getPlanoSaas(superadmin ? "pro" : accessState.effectivePlan);
  const isFreeCurrent = !superadmin && accessState.effectivePlan === "free";
  const isStartCurrent = !superadmin && accessState.effectivePlan === "start";
  const isProCurrent = superadmin || accessState.effectivePlan === "pro";
  const checkoutState = getCheckoutVisualState();
  const proximaCobranca = accessState.accessEndsAt || usuario?.planExpiresAt || billingConfig.paidUntil || "";
  const dataCobranca = proximaCobranca ? new Date(proximaCobranca).toLocaleDateString("pt-BR") : "-";
  const statusLabel = accessState.isCancelingAtPeriodEnd
    ? "Cancelamento agendado"
    : accessState.shouldShowPendingPayment
      ? "Pagamento pendente"
      : isPremiumAtivo
        ? "Ativo"
        : "Grátis";
  const policy = getPlanPolicy(usuario);
  const usuarioMonetizacao = getUsuarioMonetizacao();
  const acoesRestantes = policy.isPaid ? "Ilimitados" : String(window.MonetizationLimits?.getRemainingFreeActions?.(usuarioMonetizacao) ?? FREE_ACTION_CREDIT_LIMIT);
  const resumoBackup = atualizarFlagBackupOverLimit(criarSnapshotBackupUsuarioAtual(), false);
  const sessoesAtivas = saasSessions.filter((sessao) => sessao.clientId === (usuario?.clientId || billingConfig.clientId) && sessao.active !== false).length || 1;
  const textoBackup = `${resumoBackup.usedMb.toFixed(resumoBackup.usedMb >= 10 ? 0 : 1)} MB / ${policy.backupLabel}${resumoBackup.backup_over_limit ? " · somente leitura" : ""}`;
  const startEnabled = isStartPlanCommerciallyEnabled();
  let planos = [
    {
      slug: "free",
      name: "Grátis",
      subtitle: "Ideal para organizar a operação sem custo",
      price: "R$ 0",
      period: "/mês",
      badge: "Entrada",
      allowedTitle: "Inclui",
      allowed: ["Até 5 pedidos por dia", "Controle básico de pedidos", "Caixa simples", "Estoque básico", "Editar loja", "Visualizar loja", "Anúncios para liberar ações extras"],
      blockedTitle: "",
      blocked: [],
      highlights: ["R$ 0 por mês", "Comece agora", "Loja em preparação"],
      note: "Você pode organizar o ERP e preparar a loja antes de contratar um plano pago.",
      cta: isFreeCurrent ? "Plano atual" : "Começar grátis",
      current: isFreeCurrent,
      disabled: !isFreeCurrent,
      action: ""
    },
    {
      slug: "start",
      name: "Start",
      subtitle: "Comece a vender de verdade",
      price: "R$ 29,90",
      period: "/mês",
      badge: isStartCurrent ? "PLANO ATUAL" : startEnabled ? "MAIS POPULAR" : "EM BREVE",
      allowedTitle: "Inclui",
      allowed: ["Publicar loja", "Loja com link público", "Até 100 produtos na loja", "Sem anúncios", "Mais pedidos por dia", "Recursos intermediários"],
      blockedTitle: "",
      blocked: [],
      highlights: ["Preço promocional por tempo limitado", "Loja pública", "Até 100 produtos"],
      note: startEnabled ? "Para publicar a loja, remover anúncios e vender com link próprio." : "Preparado para contratação em breve. Seu plano atual continua normal.",
      cta: isStartCurrent ? "Plano atual" : isProCurrent ? "Incluído no Pro" : "Assinar Start",
      current: isStartCurrent,
      disabled: isStartCurrent || isProCurrent || !startEnabled,
      unavailable: !isStartCurrent && !isProCurrent && !startEnabled,
      action: startEnabled ? "start" : "start-unavailable"
    },
    {
      slug: "pro",
      name: "Pro",
      subtitle: "Para operação profissional",
      price: "R$ 59,90",
      period: "/mês",
      badge: "PROFISSIONAL",
      allowedTitle: "Inclui",
      allowed: ["Relatórios completos", "Mais telas simultâneas", "Funcionários e permissões", "Personalização avançada", "Backup maior", "Recursos avançados"],
      blockedTitle: "",
      blocked: [],
      highlights: ["Preço promocional por tempo limitado", "Operação profissional", "Personalização completa"],
      note: "O plano completo para quem quer escalar e vender mais.",
      cta: isProCurrent ? "Plano atual" : isStartCurrent ? "Upgrade para Pro" : "Assinar Pro",
      current: isProCurrent,
      disabled: isProCurrent,
      action: "pro"
    }
  ];
  const apresentacoes = getPlanPresentationData();
  const apresentacaoPorSlug = Object.fromEntries(apresentacoes.map((plan) => [plan.slug, plan]));
  planos = planos.map((plano) => {
    const apresentacao = apresentacaoPorSlug[plano.slug] || {};
    return {
      ...plano,
      ...apresentacao,
      badge: plano.badge || apresentacao.badge,
      cta: plano.cta || apresentacao.ctaLabel,
      current: plano.current,
      disabled: plano.disabled,
      unavailable: plano.unavailable,
      action: plano.action,
      allowed: apresentacao.features || plano.allowed,
      note: apresentacao.warning || apresentacao.highlight || plano.note,
      price: apresentacao.priceLabel || plano.price,
      period: apresentacao.period || plano.period,
      highlights: apresentacao.highlights || plano.highlights
    };
  });
  registrarEventoPlanoSeguro("plans_screen_opened", { effectivePlan: accessState.effectivePlan }, "plans-screen-opened");
  planos.forEach((plano) => registrarEventoPlanoSeguro("plan_card_viewed", { plan: plano.slug, current: plano.current === true }, `plan-card-viewed:${plano.slug}`));
  if (accessState.shouldShowPendingPayment) registrarEventoPlanoSeguro("payment_pending_real_viewed", { effectivePlan: accessState.effectivePlan }, "payment-pending-real-viewed");
  const abaPlanos = plansModernTab === "all" ? "all" : "current";
  const planoAtualLista = planos.find((plano) => plano.current) || planos.find((plano) => plano.slug === planoAtual.slug) || planos[0];
  const selectedSlug = planos.some((plano) => plano.slug === plansPresentationSelectedSlug) ? plansPresentationSelectedSlug : (planoAtualLista?.slug || "start");
  const planoSelecionado = planos.find((plano) => plano.slug === selectedSlug) || planos[0];

  return `
    <section class="plans-modern-screen plans-pricing-screen ui3-plans">
      <div class="plans-modern-header">
        <button class="icon-action-button" type="button" onclick="trocarTela('conta')" title="Voltar">${renderUiIcon("back")}</button>
        <h2>Planos</h2>
        <span></span>
      </div>

      <div class="plans-modern-tabs" role="tablist" aria-label="Visualização de planos">
        <button type="button" class="${abaPlanos === "current" ? "active" : ""}" onclick="setPlansModernTab('current')" aria-selected="${abaPlanos === "current"}">Meu plano</button>
        <button type="button" class="${abaPlanos === "all" ? "active" : ""}" onclick="setPlansModernTab('all')" aria-selected="${abaPlanos === "all"}">Todos os planos</button>
      </div>

      <div class="plans-pricing-hero">
        <div>
          <span class="eyebrow">Simplifica 3D</span>
          <h2>Escolha o plano ideal</h2>
          <p>Mais organização, mais vendas e uma loja pronta para crescer junto com seu negócio.</p>
        </div>
        <div class="plans-pricing-note">
          ${renderUiIcon("time")}
          <span>Valores promocionais de lançamento por tempo limitado. Os preços podem sofrer reajustes conforme novos recursos forem adicionados.</span>
        </div>
      </div>

      ${abaPlanos === "current" ? `<div class="plans-current-modern">
        <div class="row-title">
          <div>
            <span class="eyebrow">Seu plano atual</span>
            <h3>${escaparHtml(planoAtual.name || (isPremiumAtivo ? "Plano Pro" : "Plano Free"))} <small>${escaparHtml(statusLabel)}</small></h3>
            <p class="muted">${accessState.isCancelingAtPeriodEnd ? `Sua assinatura será encerrada em ${escaparHtml(dataCobranca)}. O acesso pago continua liberado até essa data.` : policy.isPaid ? "Sua conta está sem anúncios e com recursos pagos liberados conforme o plano." : "Você pode testar o ERP e preparar a loja antes de publicar."}</p>
          </div>
          <span class="plan-modern-badge ${classePlanoSaasCompacto(planoAtual.slug)}">${escaparHtml(policy.isPro ? "PRO" : policy.isStart ? "START" : "GRÁTIS")}</span>
        </div>
        <div class="plans-current-stats">
          <span><small>Pedidos restantes hoje</small><strong>${escaparHtml(acoesRestantes)}</strong></span>
          <span><small>Backup</small><strong>${escaparHtml(textoBackup)}</strong></span>
          <span><small>Dispositivos</small><strong>${sessoesAtivas}/${policy.maxDevices}</strong></span>
          <span><small>Próxima cobrança</small><strong>${escaparHtml(dataCobranca)}</strong></span>
        </div>
        <div class="plans-current-bottom">
          <span><small>Loja pública</small><strong>${policy.publicStore ? "Liberada" : "Somente visualização"}</strong></span>
          <button class="btn ghost" type="button" ${accessState.canCancelRenewal ? "data-action=\"plan-cancel\"" : accessState.canReactivateRenewal ? "data-action=\"plan-reactivate\"" : "data-action=\"open-payment\" data-slug=\"pro\""}>${renderUiIcon("config")} ${accessState.canCancelRenewal ? "Cancelar renovação" : accessState.canReactivateRenewal ? "Reativar renovação" : "Assinar Pro"}</button>
        </div>
        ${renderPlanPaymentNotice(accessState, checkoutState)}
      </div>
      <button class="plans-help-card plans-view-all-card" type="button" onclick="setPlansModernTab('all')">
        ${renderUiIcon("assinatura")}
        <span><strong>Ver todos os planos</strong><small>Compare Grátis, Start e Pro antes de trocar.</small></span>
        <b>›</b>
      </button>` : `
      <div class="plans-current-modern plans-current-compact">
        <span class="eyebrow">Seu plano atual</span>
        <strong>${escaparHtml(planoAtualLista.name || planoAtual.name || "Plano atual")}</strong>
        <small class="muted">${escaparHtml(statusLabel)} · ${policy.publicStore ? "Loja pública liberada" : "Loja em visualização"}</small>
      </div>`}

      ${abaPlanos === "all" ? renderPlanPaymentNotice(accessState, checkoutState) : ""}
      ${abaPlanos === "all" ? `
      ${renderPlanMobileTabs(planos, selectedSlug)}
      <div class="plans-pricing-grid plans-carousel" aria-label="Cards de planos" onscroll="sincronizarPlanoApresentacaoPorScroll(this)">
        ${planos.map((plan) => renderModernPlanOption(plan, planoAtualLista)).join("")}
      </div>
      ` : ""}

      <button class="plans-help-card" type="button" onclick="trocarTela('feedback')">
        ${renderUiIcon("feedback")}
        <span><strong>Dúvidas?</strong><small>Fale com nosso time ou acesse a central de ajuda.</small></span>
        <b>›</b>
      </button>
    </section>
  `;
}

function setPlansModernTab(tab = "current") {
  plansModernTab = tab === "all" ? "all" : "current";
  renderApp();
}

function renderModernPlanOption(plan = {}, currentPlan = {}) {
  const slug = normalizarSlugPlano(plan.slug || "free");
  const short = slug === "pro" ? "PRO" : slug === "start" ? "START" : "GRÁTIS";
  const disabled = plan.current || (plan.disabled && !plan.unavailable);
  const selected = plansPresentationSelectedSlug === slug;
  const click = plan.unavailable
    ? `data-action="plan-start-unavailable"`
    : disabled
    ? ""
    : ["start", "pro"].includes(plan.action)
      ? `data-action="open-payment" data-slug="${escaparAttr(plan.action)}"`
      : plan.action
        ? `onclick="trocarTela('${escaparAttr(plan.action)}')"`
        : "";
  const priceText = String(plan.price || plan.priceLabel || "R$ 0");
  const mainPrice = priceText.replace(/^R\$\s*/, "");
  return `
    <article class="plan-modern-option plan-tier-card plan-tier-${escaparAttr(slug)} ${plan.current ? "current" : ""} ${plan.disabled ? "disabled" : ""} ${selected ? "is-selected" : ""}" tabindex="0" data-plan-slug="${escaparAttr(slug)}" onclick="if(!event.target.closest('button,a,[data-action]')) selecionarPlanoApresentacao('${escaparAttr(slug)}')" onpointermove="moverPlanoApresentacaoInterativo(event)" onpointerleave="resetarPlanoApresentacaoInterativo(event)" ontouchmove="moverPlanoApresentacaoInterativo(event)">
      ${plan.current ? `<span class="plan-current-ribbon">Atual</span>` : ""}
      ${plan.badge ? `<span class="plan-tier-badge">${escaparHtml(plan.badge)}</span>` : ""}
      <div class="row-title">
        <span class="plan-tier-avatar">${short.charAt(0)}</span>
        <div>
          <h3>${escaparHtml(plan.name)}</h3>
          <p class="muted">${escaparHtml(plan.subtitle || plan.headline || "")}</p>
        </div>
        <span class="plan-modern-badge ${classePlanoSaasCompacto(slug)}">${escaparHtml(short)}</span>
      </div>
      ${renderPlanMiniDashboard(plan)}
      <p class="plan-tier-description">${escaparHtml(plan.description || plan.presentation || "")}</p>
      <div class="plan-tier-price"><small>R$</small><strong>${escaparHtml(mainPrice)}</strong><span>${escaparHtml(plan.period || "/mês")}</span></div>
      ${plan.visualLabel ? `<span class="plan-visual-label">${escaparHtml(plan.visualLabel)}</span>` : ""}
      <div class="plan-tier-highlights">
        ${(plan.highlights || []).map((item) => `<b>${escaparHtml(item)}</b>`).join("")}
      </div>
      <div class="plan-tier-section">
        <strong>${escaparHtml(plan.allowedTitle || "Inclui")}</strong>
        ${renderPlanFeatureList(plan.allowed || plan.features, "allowed")}
      </div>
      ${plan.blocked?.length ? `
        <div class="plan-tier-section blocked">
          <strong>${escaparHtml(plan.blockedTitle || "Bloqueado")}</strong>
          ${renderPlanFeatureList(plan.blocked, "blocked")}
        </div>
      ` : ""}
      <div class="plan-tier-note">${escaparHtml(plan.note || "")}</div>
      ${selected ? renderPlanCardBrochure(plan, currentPlan) : ""}
      <button class="btn plan-tier-button ${plan.unavailable ? "is-unavailable" : ""}" type="button" ${click} ${disabled ? "disabled" : ""} ${plan.unavailable ? "aria-disabled=\"true\"" : ""}>${escaparHtml(plan.cta || "Escolher plano")}</button>
    </article>
  `;
}

function renderTrialPremiumAtivoCard(diasTrial = 0) {
  const textoDias = diasTrial === 1 ? "1 dia restante" : `${diasTrial} dias restantes`;
  return `
    <div class="plan-status-card trial" aria-label="Acesso PRO ativo">
      <div class="plan-card-top">
        <span class="plan-badge plan-badge-trial">PRO ativo</span>
        <strong class="plan-days">${textoDias}</strong>
      </div>
      <h3>Você está com acesso PRO</h3>
      <p>Ao final do período confirmado, sua conta segue a regra atual da assinatura.</p>
      <div class="actions">
        <button class="btn plan-primary-button" type="button" data-action="open-payment" data-slug="pro">Assinar Pro</button>
        <button class="btn ghost" type="button" data-action="open-screen" data-screen="dashboard">Continuar usando</button>
      </div>
    </div>
  `;
}

function renderPlanoPremiumAtivoCard(estadoPlano, precoVigente, superadmin = false, diasPlano = 0) {
  const validade = superadmin
    ? "Acesso interno liberado"
    : diasPlano > 0 && diasPlano < 9999
      ? `${diasPlano} dia(s) restantes`
      : "Assinatura ativa";
  return `
    <div class="plan-card featured plan-card-premium plan-card-active">
      <div class="plan-card-top">
        <span class="plan-badge">PRO ativo</span>
        <span class="status-badge badge-pago">${escaparHtml(validade)}</span>
      </div>
      <h3>PRO</h3>
      <div class="plan-price">${formatarMoeda(precoVigente)}<small>/mês</small></div>
      ${renderPlanBenefitList([
        "Ações ilimitadas",
        "Sem anúncios",
        "Relatórios avançados",
        "Funcionários e permissões",
        "Backup de 1 GB",
        "Temas e identidade visual",
        "Suporte prioritário"
      ])}
      <p class="muted plan-card-footnote">Plano completo para operações que precisam de mais controle e personalização.</p>
      <div class="actions">
        <button class="btn ghost" type="button" data-action="open-screen" data-screen="dashboard">Continuar usando</button>
        ${superadmin
          ? `<button class="btn secondary" type="button" onclick="trocarTela('superadmin')">Gerenciar clientes</button>`
          : `<button class="btn secondary" type="button" onclick="sincronizarSupabase()">Restaurar compra</button>`}
      </div>
    </div>
  `;
}

function renderPlanBenefitList(beneficios = []) {
  return `
    <ul class="plan-benefit-list">
      ${beneficios.map((item) => `<li>${escaparHtml(item)}</li>`).join("")}
    </ul>
  `;
}

function renderPlanoSaasCard(plano, options = {}) {
  const superadmin = isSuperAdmin();
  const isPremium = ["start", "pro", "premium_trial"].includes(plano.slug);
  const preco = isPremium ? Number(options.preco || getPrecoPagoVigenteLocal()) : 0;
  const isPro = plano.slug === "pro" || plano.slug === "premium_trial";
  const beneficios = isPremium
    ? (isPro ? ["Sem anúncios", "Relatórios completos", "Funcionários e permissões", "Personalização avançada", "Backup maior", "Recursos avançados"] : ["Publicar loja", "Sem anúncios", "Até 100 produtos na loja", "Loja com link público", "Mais pedidos por dia", "Recursos intermediários"])
    : ["Controle básico de pedidos", "Caixa simples", "Estoque básico", "Editar loja", "Visualizar loja", "Anúncios para liberar ações extras"];

  return `
    <div class="plan-card ${isPremium ? "featured plan-card-premium" : "plan-card-free"}">
      <div class="plan-card-top">
        <span class="plan-badge ${isPremium ? "" : "plan-badge-free"}">${isPremium ? "Recomendado" : "Gratuito"}</span>
        ${isPremium ? `<span class="muted">Mais completo</span>` : ""}
      </div>
      <h3>${isPremium ? (plano.slug === "start" ? "Start" : "Pro") : "Grátis"}</h3>
      ${isPremium
        ? `<div class="plan-price">${formatarMoeda(preco)}<small>/mês</small></div>
           <p class="muted plan-card-note">Primeiro mês por ${formatarMoeda(PREMIUM_FIRST_MONTH_PRICE)}.</p>`
        : `<p class="plan-free-copy">Para começar sem custo e organizar o básico da operação.</p>`}
      ${renderPlanBenefitList(beneficios)}
      ${isPremium ? `<p class="muted plan-card-footnote">Preço promocional por tempo limitado.</p>` : ""}
      ${isPremium && options.isTrial ? `<p class="muted plan-card-note">Assinar agora mantém o acesso PRO normalmente enquanto o pagamento é confirmado.</p>` : ""}
      <div class="actions single">
        ${superadmin
          ? `<button class="btn ghost" type="button" disabled>Não aplicável</button>`
          : isPremium
            ? `<button class="btn plan-primary-button" type="button" data-action="open-payment" data-slug="${escaparAttr(plano.slug === "start" ? "start" : "pro")}">Assinar ${escaparHtml(plano.slug === "start" ? "Start" : "Pro")}</button>`
            : `<button class="btn ghost plan-free-button" type="button" data-action="open-screen" data-screen="dashboard">Continuar no plano gratuito</button>`}
      </div>
    </div>
  `;
}

function renderMinhaAssinatura() {
  verificarVencimentoPlanoLocal(false);
  const cliente = getClienteSaasAtual();
  const assinatura = getAssinaturaSaas();
  const plano = getPlanoSaasAtual();
  const status = getPlanoAtual();
  const pagamentos = saasPayments
    .filter((pagamento) => !cliente?.id || pagamento.clientId === cliente.id || pagamento.clientId === billingConfig.clientId)
    .sort((a, b) => (Date.parse(b.createdAt || 0) || 0) - (Date.parse(a.createdAt || 0) || 0));
  const ultimo = pagamentos[0];
  const inicio = assinatura?.startedAt || cliente?.createdAt || "";
  const vencimento = assinatura?.expiresAt || assinatura?.nextBillingAt || billingConfig.paidUntil || "";
  const diasRestantes = vencimento ? getRemainingDays(vencimento) : status.diasRestantes;

  const linhas = pagamentos.map((pagamento) => `
    <div class="payment-row">
      <span>${new Date(pagamento.createdAt || Date.now()).toLocaleDateString("pt-BR")}</span>
      <strong>${escaparHtml(getPlanoSaas(pagamento.planSlug).name)}</strong>
      <span>${formatarMoeda(pagamento.amount)}</span>
      <span class="status-badge ${classeStatusPlano(pagamento.status)}">${escaparHtml(pagamento.status)}</span>
      <span>${escaparHtml(pagamento.paymentMethod || "-")}</span>
      <span>${escaparHtml(pagamento.mercadoPagoPaymentId || "-")}</span>
    </div>
  `).join("") || `<p class="empty">Nenhum pagamento confirmado ainda.</p>`;

  return `
    <section class="card">
      <div class="card-header">
        <h2>💳 Minha Assinatura</h2>
        <span class="status-badge ${classeStatusPlano(status.status)}">${escaparHtml(status.nome)}</span>
      </div>
      <p class="muted">Seu plano só é liberado após a confirmação real do pagamento pelo Mercado Pago.</p>

      <div class="metrics">
        <div class="metric"><span>Cliente ID</span><strong>${escaparHtml(cliente?.clientCode || billingConfig.clientId || "não vinculado")}</strong></div>
        <div class="metric"><span>Plano atual</span><strong>${escaparHtml(plano.name)}</strong></div>
        <div class="metric"><span>Status</span><strong>${escaparHtml(status.descricao || status.status)}</strong></div>
        <div class="metric"><span>Dias restantes</span><strong>${diasRestantes >= 9999 ? "Livre" : Math.max(0, diasRestantes || 0)}</strong></div>
        <div class="metric"><span>Início do plano</span><strong>${inicio ? new Date(inicio).toLocaleDateString("pt-BR") : "-"}</strong></div>
        <div class="metric"><span>Vencimento / cobrança</span><strong>${vencimento ? new Date(vencimento).toLocaleDateString("pt-BR") : "-"}</strong></div>
      </div>

      <div class="danger-zone">
        <h2 class="section-title">Último pagamento</h2>
        <div class="metrics">
          <div class="metric"><span>Valor</span><strong>${ultimo ? formatarMoeda(ultimo.amount) : "-"}</strong></div>
          <div class="metric"><span>Data</span><strong>${ultimo?.createdAt ? new Date(ultimo.createdAt).toLocaleDateString("pt-BR") : "-"}</strong></div>
          <div class="metric"><span>Status</span><strong>${escaparHtml(ultimo?.status || "-")}</strong></div>
          <div class="metric"><span>Método</span><strong>${escaparHtml(ultimo?.paymentMethod || "-")}</strong></div>
          <div class="metric"><span>Payment ID</span><strong>${escaparHtml(ultimo?.mercadoPagoPaymentId || "-")}</strong></div>
          <div class="metric"><span>Subscription ID</span><strong>${escaparHtml(assinatura?.mercadoPagoSubscriptionId || "-")}</strong></div>
        </div>
        <div class="actions">
          <button class="btn" type="button" data-action="plan-renew" data-slug="${escaparAttr(plano.slug === "free" ? "premium" : plano.slug)}">Renovar plano</button>
          <button class="btn secondary" type="button" data-action="open-screen" data-screen="assinatura">Alterar plano</button>
          <button class="btn ghost" type="button" data-action="plan-cancel">Cancelar assinatura</button>
          <button class="btn ghost" type="button" data-action="plan-support">Falar com suporte</button>
        </div>
      </div>

      <h2 class="section-title">Histórico de pagamentos</h2>
      <div class="payment-table">${linhas}</div>
    </section>
  `;
}

function renderSobre() {
  return `
    <section class="card about-card">
      <div class="card-header">
        <h2>Sobre</h2>
        <span class="status-badge">v1.0</span>
      </div>
      <div class="about-brand">
        ${renderMarcaProjeto("about-logo", "Logo Simplifica 3D")}
        <div>
          <strong>Simplifica 3D</strong>
          <span class="muted">Sistema SaaS para gestão de impressão 3D</span>
        </div>
      </div>
      <div class="metrics">
        <div class="metric"><span>Versão do sistema</span><strong>${escaparHtml(APP_VERSION)}</strong></div>
        <div class="metric"><span>Aplicativo</span><strong>Simplifica 3D</strong></div>
        <div class="metric"><span>Suporte</span><strong><a href="mailto:simplifica3d.app@gmail.com">simplifica3d.app@gmail.com</a></strong></div>
        <div class="metric"><span>Plataformas</span><strong>PWA + APK</strong></div>
      </div>
      <p class="muted legal-copy">© 2026 Simplifica 3D - Todos os direitos reservados</p>
    </section>
  `;
}

function renderDocumentoLegalPage(tipo = "termos") {
  const documento = getDocumentoLegal(tipo);
  return `
    <section class="card legal-page">
      <div class="card-header">
        <h2>${escaparHtml(documento.titulo)}</h2>
        <span class="status-badge">Legal</span>
      </div>
      <p class="muted">${escaparHtml(documento.subtitulo)}</p>
      <div class="legal-content legal-page-content">
        ${documento.secoes.map((secao) => `
          <section class="legal-section">
            <h3>${escaparHtml(secao.titulo)}</h3>
            <ul>
              ${secao.itens.map((item) => `<li>${escaparHtml(item)}</li>`).join("")}
            </ul>
          </section>
        `).join("")}
        <p class="muted">${escaparHtml(documento.rodape)}</p>
      </div>
    </section>
  `;
}

function renderFeedback() {
  const feedbackStatus = window.__feedbackManualStatus || {};
  const sugestoesOrdenadas = [...sugestoes].sort((a, b) => (Number(b.votos) || 0) - (Number(a.votos) || 0) || Date.parse(b.atualizadoEm || 0) - Date.parse(a.atualizadoEm || 0));
  const listaSugestoes = sugestoesOrdenadas.slice(0, 20).map((item, indice) => `
    <div class="suggestion-item">
      <div>
        <strong>${indice + 1}. ${escaparHtml(item.titulo)}</strong>
        <span class="muted">${Number(item.votos) || 1} ocorrência(s) • ${escaparHtml(item.category || "geral")} • ${new Date(item.atualizadoEm || item.criadoEm).toLocaleString("pt-BR")}</span>
      </div>
      <button class="icon-button" onclick="votarSugestao('${escaparAttr(item.id)}')" title="Repetir sugestão">+</button>
    </div>
  `).join("") || `<p class="empty">Nenhuma sugestão registrada ainda.</p>`;

  return `
    <section class="card">
      <div class="card-header">
        <h2>${renderUiIcon("feedback")} Sugestões de melhorias</h2>
        <span class="status-badge">Ideias</span>
      </div>
      <p class="muted">Envie uma ideia ou relate um problema. As informações necessárias para o suporte são anexadas automaticamente.</p>
      <div class="actions">
        <button class="btn secondary" onclick="registrarSugestaoNfe()">Quero emissão de NF-e</button>
      </div>

      <div class="danger-zone">
        <h2 class="section-title">Ajuda e Feedback</h2>
        <div class="sync-grid">
          <label class="field">
            <span>Tipo</span>
            <select id="feedbackTipo">
              <option value="bug_report">Relatar problema</option>
              <option value="suggestion" selected>Enviar sugestão</option>
              <option value="improvement">Solicitar melhoria</option>
              <option value="question">Informar dúvida</option>
              <option value="complaint">Reclamação</option>
              <option value="other">Outro</option>
            </select>
          </label>
          <label class="field">
            <span>Título</span>
            <input id="feedbackTitulo" maxlength="120" placeholder="Ex.: melhorar relatório mensal">
          </label>
        </div>
        <label class="field">
          <span>Descrição</span>
          <textarea id="feedbackDescricao" rows="4" maxlength="1200" placeholder="Conte o que aconteceu ou o que você gostaria de melhorar"></textarea>
        </label>
        <div class="actions">
          <button class="btn" onclick="enviarSugestaoProduto()" ${feedbackStatus.status === "sending" ? "disabled" : ""}>Sugerir melhoria</button>
          <button class="btn secondary" onclick="enviarFeedbackManual()" ${feedbackStatus.status === "sending" ? "disabled" : ""}>${feedbackStatus.status === "sending" ? "Enviando..." : "Enviar feedback"}</button>
        </div>
        ${feedbackStatus.message ? `<p class="muted feedback-status ${escaparAttr(feedbackStatus.status || "")}">${escaparHtml(feedbackStatus.message)}</p>` : ""}
      </div>

      <h2 class="section-title">Sugestões mais pedidas</h2>
      <div class="history-list">
        ${listaSugestoes}
      </div>

    </section>
  `;
}

function salvarFeedbackConfig() {
  appConfig.telemetryEnabled = !!document.getElementById("telemetryEnabledConfig")?.checked;
  salvarDados();
  registrarHistorico("Diagnóstico", appConfig.telemetryEnabled ? "Registro local ativado" : "Registro local pausado");
  renderApp();
}

function adicionarSugestao() {
  const texto = document.getElementById("novaSugestaoTexto")?.value || "";
  if (!registrarSugestaoLocal(texto, "manual")) {
    alert("Digite uma sugestão com pelo menos 4 caracteres.");
    return;
  }
  registrarHistorico("Sugestão", texto.trim());
  renderApp();
}

function lerFormularioFeedbackManual() {
  return {
    type: document.getElementById("feedbackTipo")?.value || "sugestao",
    title: String(document.getElementById("feedbackTitulo")?.value || "").trim(),
    description: String(document.getElementById("feedbackDescricao")?.value || "").trim()
  };
}

function montarPayloadFeedbackManual(form) {
  const usuario = getUsuarioAtual();
  const email = normalizarEmail(syncConfig.supabaseEmail || usuario?.email || billingConfig.licenseEmail || "");
  const planState = getPlanAccessState(usuario || {});
  const mensagem = form.description.slice(0, 1200);
  return {
    user_id: pareceUuid(syncConfig.supabaseUserId) ? syncConfig.supabaseUserId : null,
    user_email: email || null,
    user_name: usuario?.nome || null,
    type: form.type,
    title: form.title.slice(0, 120),
    message: mensagem,
    description: mensagem,
    app_version: APP_VERSION,
    device_model: syncConfig.deviceName || deviceId || navigator.platform || "",
    os_version: navigator.userAgent || "",
    platform: window.Capacitor?.getPlatform?.() || (navigator.userAgentData?.mobile ? "mobile-web" : "web"),
    screen: telaAtual || "",
    screen_name: telaAtual || "",
    action: "manual_feedback",
    plan_at_time: planState.currentPlan || "",
    metadata: {
      device_id: deviceId,
      company_id: billingConfig.companyId || "",
      client_id: billingConfig.clientId || ""
    }
  };
}

async function salvarFeedbackManualSupabase(form) {
  if (window.DiagnosticsService?.reportFeedback) {
    const resultado = await window.DiagnosticsService.reportFeedback(montarPayloadFeedbackManual(form));
    if (resultado?.queued || resultado?.ok) return resultado;
  }
  return requisicaoSupabase("/rest/v1/app_feedback_reports", {
    method: "POST",
    headers: { Prefer: "return=minimal" },
    body: JSON.stringify(montarPayloadFeedbackManual(form))
  });
}

function normalizarTipoSugestaoApp(tipo = "suggestion") {
  const valor = String(tipo || "").toLowerCase();
  if (["bug", "bug_report"].includes(valor)) return "bug";
  if (["feature", "melhoria", "improvement", "recurso"].includes(valor)) return "feature";
  return "suggestion";
}

function inferirCategoriaSugestao(form = {}) {
  const texto = normalizarTextoSugestao(`${form.category || ""} ${form.title || form.titulo || ""} ${form.description || ""}`);
  if (/\bnf\s*e\b|\bnfe\b|nota fiscal|emissao fiscal/.test(texto)) return "nfe";
  if (/pedido|orcamento|orcamento/.test(texto)) return "pedidos";
  if (/financeiro|caixa|pagamento|relatorio/.test(texto)) return "financeiro";
  return String(form.category || "geral").toLowerCase().replace(/[^a-z0-9_]/g, "_") || "geral";
}

function montarPayloadSugestaoApp(form = {}) {
  const usuario = getUsuarioAtual();
  const clientId = getClientIdAtual() || billingConfig.clientId || "";
  return {
    user_id: pareceUuid(syncConfig.supabaseUserId) ? syncConfig.supabaseUserId : null,
    client_id: pareceUuid(clientId) ? clientId : null,
    type: normalizarTipoSugestaoApp(form.type),
    category: inferirCategoriaSugestao(form),
    title: String(form.title || form.titulo || "Sugestão").trim().slice(0, 140),
    description: String(form.description || "").trim().slice(0, 1600),
    status: "new",
    metadata: {
      user_email: normalizarEmail(syncConfig.supabaseEmail || usuario?.email || billingConfig.licenseEmail || ""),
      user_name: usuario?.nome || "",
      app_version: APP_VERSION,
      screen_name: telaAtual || "",
      device_id: deviceId || ""
    }
  };
}

async function salvarSugestaoSupabase(payload) {
  return requisicaoSupabase("/rest/v1/app_suggestions", {
    method: "POST",
    headers: { Prefer: "return=minimal" },
    body: JSON.stringify(payload)
  });
}

async function registrarSugestaoProduto(form = {}) {
  const payload = montarPayloadSugestaoApp(form);
  if (!payload.title || payload.title.length < 4) {
    throw new Error("Informe uma sugestão com pelo menos 4 caracteres.");
  }
  registrarSugestaoLocal(payload.title, "produto", {
    type: payload.type,
    category: payload.category,
    description: payload.description,
    status: payload.status,
    userId: payload.user_id || "",
    clientId: payload.client_id || getClientIdAtual() || ""
  });
  try {
    await salvarSugestaoSupabase(payload);
  } catch (erro) {
    registrarErroAplicacaoSilencioso("SAVE_APP_SUGGESTION_FAILED", erro, "Salvar sugestão", { category: payload.category, type: payload.type });
  }
  salvarDados();
  registrarHistorico("Sugestão", `${payload.category}: ${payload.title}`);
  return payload;
}

async function enviarSugestaoProduto() {
  const form = lerFormularioFeedbackManual();
  if (!form.title || form.title.length < 4) {
    window.__feedbackManualStatus = { status: "error", message: "Informe um título com pelo menos 4 caracteres." };
    renderApp();
    return;
  }
  window.__feedbackManualStatus = { status: "sending", message: "Registrando sugestão..." };
  renderApp();
  try {
    await registrarSugestaoProduto({
      ...form,
      type: normalizarTipoSugestaoApp(form.type === "bug" ? "bug" : "feature")
    });
    window.__feedbackManualStatus = { status: "success", message: "Obrigado! Sua sugestão foi registrada." };
    mostrarToast("Obrigado! Sua sugestão foi registrada.", "sucesso", 4200);
  } catch (erro) {
    window.__feedbackManualStatus = { status: "error", message: erro.message || "Não foi possível registrar a sugestão." };
    mostrarToast(window.__feedbackManualStatus.message, "erro", 5000);
  }
  renderApp();
}

async function registrarSugestaoNfe() {
  try {
    await registrarSugestaoProduto({
      type: "feature",
      category: "nfe",
      title: "Quero emissão de NF-e",
      description: "Pedido rápido do usuário para emissão de NF-e dentro do Simplifica 3D."
    });
    mostrarToast("Obrigado! Sua sugestão foi registrada.", "sucesso", 4200);
  } catch (erro) {
    mostrarToast(erro.message || "Não foi possível registrar a sugestão.", "erro", 5000);
  }
  renderApp();
}

async function enviarFeedbackManual() {
  const form = lerFormularioFeedbackManual();
  if (!form.title || form.title.length < 4) {
    window.__feedbackManualStatus = { status: "error", message: "Informe um título com pelo menos 4 caracteres." };
    renderApp();
    return;
  }
  if (!form.description || form.description.length < 8) {
    window.__feedbackManualStatus = { status: "error", message: "Descreva o feedback com um pouco mais de detalhe." };
    renderApp();
    return;
  }

  window.__feedbackManualStatus = { status: "sending", message: "Enviando feedback..." };
  renderApp();

  try {
    await salvarFeedbackManualSupabase(form);
    registrarSugestaoLocal(`${form.title}: ${form.description}`, "feedback");
    registrarHistorico("Feedback", `${form.type}: ${form.title}`);
    window.__feedbackManualStatus = { status: "success", message: "Obrigado! Seu relato foi enviado e será analisado." };
    mostrarToast("Obrigado! Seu relato foi enviado e será analisado.", "sucesso", 4000);
  } catch (erro) {
    registrarSugestaoLocal(`${form.title}: ${form.description}`, "feedback-local");
    registrarErroAplicacaoSilencioso("FEEDBACK_SUBMIT_FAILED", erro, "Enviar feedback manual", { type: form.type });
    window.__feedbackManualStatus = { status: "error", message: "Não foi possível enviar agora. O feedback ficou salvo neste aparelho." };
    mostrarToast("Erro ao enviar feedback. Ficou salvo localmente.", "erro", 5000);
  }
  renderApp();
}

function votarSugestao(id) {
  const item = sugestoes.find((sugestao) => String(sugestao.id) === String(id));
  if (!item) return;
  registrarSugestaoLocal(item.titulo, "repetida", {
    type: item.type || "suggestion",
    category: item.category || "geral",
    description: item.description || ""
  });
  renderApp();
}

function limparDiagnosticos() {
  if (!confirm("Limpar os registros locais de erros?")) return;
  diagnostics = [];
  salvarDados();
  renderApp();
}

function registrarDiagnosticoManual() {
  registrarDiagnostico("teste", "Registro manual criado", "Usado para confirmar se o painel está salvando os dados.");
  renderApp();
}

function escolherPlanoSaas(slug = "free") {
  const plano = getPlanoSaas(slug);
  if (!["free", "start", "pro"].includes(plano.slug)) {
    alert("Plano indisponível.");
    return;
  }
  if (plano.slug === "free") {
    mostrarToast("Você continua no plano gratuito.", "info");
    trocarTela("dashboard");
    return;
  }
  const clientId = getClientIdAtual() || billingConfig.clientId || criarIdLocal("client");
  if (!billingConfig.clientId) billingConfig.clientId = clientId;
  let assinatura = getAssinaturaSaas(clientId);
  if (!assinatura) {
    assinatura = normalizarAssinaturaSaas({ clientId, planSlug: "free", activePlan: "free", status: "active" });
    saasSubscriptions.push(assinatura);
  }
  if (plano.slug === "free") {
    assinatura.pendingPlan = "";
    assinatura.paymentStatus = "none";
    billingConfig.pendingPlan = "";
    billingConfig.paymentStatus = "none";
  }
  billingConfig.planSlug = assinatura.activePlan || assinatura.planSlug || "free";
  billingConfig.activePlan = assinatura.activePlan || assinatura.planSlug || "free";
  billingConfig.monthlyPrice = isPlanoPagoSlug(billingConfig.activePlan) ? getPlanoSaas(billingConfig.activePlan).price : 0;
  billingConfig.subscriptionId = assinatura.id;
  salvarDados();
  registrarAuditoria(plano.price > 0 ? "checkout solicitado" : "alteração plano", { plano: plano.slug }, clientId);
  if (plano.slug === "free") {
    ativarPlanoClienteLocal(clientId, "free", "active", 0, { origem: "escolha_free" });
    renderApp();
    return;
  }
  abrirLinkMercadoPago(plano.slug);
  renderApp();
}

function iniciarTesteGratis(slug = "premium_trial") {
  mostrarToast("A ativação temporária foi removida. Escolha Start ou Pro para liberar recursos pagos.", "info", 5200);
  trocarTela("assinatura");
  return;
  const plano = getPlanoSaas(slug);
  const usuario = getUsuarioAtual();
  const email = normalizarEmail(usuario?.email || syncConfig.supabaseEmail || billingConfig.licenseEmail || usuarioAtualEmail || "");
  if (!email) {
    alert("Entre ou crie uma conta antes de escolher um plano pago.");
    trocarTela("admin");
    return;
  }

  if (billingConfig.trialConsumedAt || getAssinaturaSaas(getClientIdAtual() || billingConfig.clientId)?.trialConsumedAt) {
    mostrarToast("A ativação temporária não está mais disponível nesta conta.", "info", 6500);
    trocarTela("assinatura");
    return;
  }

  if (!billingConfig.trialStartedAt) {
    billingConfig.licenseEmail = email;
    billingConfig.planSlug = plano.slug;
    billingConfig.activePlan = plano.slug;
    billingConfig.pendingPlan = "";
    billingConfig.paymentStatus = "none";
    billingConfig.subscriptionStatus = "trialing";
    billingConfig.monthlyPrice = plano.price;
    billingConfig.trialStartedAt = new Date().toISOString();
    billingConfig.trialExpiresAt = calcularFimTrial(billingConfig.trialStartedAt, billingConfig.trialDays);
    billingConfig.trialConsumedAt = billingConfig.trialStartedAt;
    billingConfig.isTrialActive = true;
    billingConfig.licenseStatus = "trial";
    const clientId = getClientIdAtual() || billingConfig.clientId || criarIdLocal("client");
    billingConfig.clientId = clientId;
    let assinatura = getAssinaturaSaas(clientId);
    if (!assinatura) {
      assinatura = normalizarAssinaturaSaas({ clientId, planSlug: plano.slug, status: "trialing" });
      saasSubscriptions.push(assinatura);
    }
    assinatura.planSlug = plano.slug;
    assinatura.planId = plano.slug;
    assinatura.activePlan = plano.slug;
    assinatura.pendingPlan = "";
    assinatura.paymentStatus = "none";
    assinatura.subscriptionStatus = "trialing";
    assinatura.status = "trialing";
    assinatura.statusAssinatura = "trialing";
    assinatura.promoUsed = false;
    assinatura.billingVariant = "premium_first_month";
    assinatura.startedAt = billingConfig.trialStartedAt;
    assinatura.currentPeriodStart = billingConfig.trialStartedAt;
    assinatura.currentPeriodEnd = billingConfig.trialExpiresAt;
    assinatura.expiresAt = assinatura.currentPeriodEnd;
    assinatura.nextBillingAt = assinatura.currentPeriodEnd;
    assinatura.planExpiresAt = assinatura.currentPeriodEnd;
    assinatura.trialStartedAt = billingConfig.trialStartedAt;
    assinatura.trialExpiresAt = billingConfig.trialExpiresAt;
    assinatura.trialConsumedAt = billingConfig.trialConsumedAt;
    assinatura.isTrialActive = true;
    billingConfig.subscriptionId = assinatura.id;
    billingConfig.paidUntil = assinatura.expiresAt;
    billingConfig.planExpiresAt = assinatura.expiresAt;
    if (!registrarDispositivoLicenca(email)) return;
    salvarDados();
    registrarHistorico("Assinatura", "Acesso temporário iniciado");
    registrarAuditoria("acesso temporário iniciado", { plano: plano.slug }, clientId);
  }

  renderApp();
}

function getClienteCodigoAtual() {
  const cliente = getClienteSaasAtual();
  return cliente?.clientCode || billingConfig.clientId || getClientIdAtual() || "";
}

function garantirAssinaturaClienteLocal(clientId = getClientIdAtual()) {
  const idCliente = clientId || billingConfig.clientId || criarIdLocal("client");
  let assinatura = getAssinaturaSaas(idCliente);
  if (!assinatura) {
    assinatura = normalizarAssinaturaSaas({ clientId: idCliente, planSlug: "free", status: "active" });
    saasSubscriptions.push(assinatura);
  }
  if (!billingConfig.clientId) billingConfig.clientId = idCliente;
  billingConfig.subscriptionId = assinatura.id;
  return assinatura;
}

function ativarPlanoClienteLocal(clientId, slug, status = "active", dias = 30, detalhes = {}) {
  const plano = getPlanoSaas(slug);
  const agora = new Date().toISOString();
  const assinatura = garantirAssinaturaClienteLocal(clientId);
  const expiresAt = dias > 0 ? new Date(Date.now() + dias * 24 * 60 * 60 * 1000).toISOString() : "";
  const planPrice = isPlanoPagoSlug(plano.slug)
    ? Math.max(0, Number(detalhes.planPrice ?? detalhes.plan_price ?? assinatura.planPrice ?? plano.price) || plano.price)
    : 0;
  assinatura.planSlug = plano.slug;
  assinatura.planId = plano.slug;
  assinatura.activePlan = plano.slug;
  assinatura.pendingPlan = "";
  assinatura.pendingStartedAt = "";
  assinatura.paymentStatus = status === "pending" ? "pending" : "none";
  assinatura.subscriptionStatus = plano.slug === "premium_trial" ? "trialing" : isPlanoPagoSlug(plano.slug) ? "active" : "free";
  assinatura.cancelAtPeriodEnd = false;
  assinatura.status = normalizarStatusPlano(status);
  assinatura.statusAssinatura = assinatura.status;
  assinatura.promoUsed = detalhes.promoUsed === true || assinatura.promoUsed === true;
  assinatura.billingVariant = normalizarBillingVariant(detalhes.billingVariant || getBillingVariantAssinatura(assinatura));
  assinatura.planPrice = planPrice;
  assinatura.priceLocked = isPlanoPagoSlug(plano.slug);
  assinatura.currentPeriodStart = agora;
  assinatura.currentPeriodEnd = expiresAt;
  assinatura.startedAt = assinatura.startedAt || agora;
  assinatura.expiresAt = expiresAt;
  assinatura.nextBillingAt = expiresAt;
  assinatura.planExpiresAt = expiresAt;
  assinatura.trialStartedAt = plano.slug === "premium_trial" ? agora : "";
  assinatura.trialExpiresAt = plano.slug === "premium_trial" ? expiresAt : "";
  assinatura.trialConsumedAt = plano.slug === "premium_trial" ? (assinatura.trialConsumedAt || agora) : assinatura.trialConsumedAt || "";
  assinatura.isTrialActive = plano.slug === "premium_trial" && !!expiresAt;
  assinatura.overdueSince = "";

  const cliente = getClienteSaasPorId(clientId);
  if (cliente) {
    cliente.planoAtual = plano.slug;
    cliente.activePlan = plano.slug;
    cliente.pendingPlan = "";
    cliente.pendingStartedAt = "";
    cliente.paymentStatus = assinatura.paymentStatus;
    cliente.subscriptionStatus = assinatura.subscriptionStatus;
    cliente.cancelAtPeriodEnd = false;
    cliente.currentPeriodEnd = expiresAt;
    cliente.statusAssinatura = assinatura.statusAssinatura;
    cliente.status = status === "blocked" ? "blocked" : "active";
    cliente.planPrice = planPrice;
    cliente.priceLocked = isPlanoPagoSlug(plano.slug);
    cliente.planExpiresAt = expiresAt;
    cliente.trialStartedAt = assinatura.trialStartedAt;
    cliente.trialExpiresAt = assinatura.trialExpiresAt;
    cliente.trialConsumedAt = assinatura.trialConsumedAt || cliente.trialConsumedAt || "";
    cliente.isTrialActive = assinatura.isTrialActive;
    cliente.updatedAt = agora;
  }

  getUsuariosDoCliente(clientId).forEach((usuario) => {
    usuario.planStatus = status;
    usuario.planExpiresAt = expiresAt;
    if (status !== "blocked") {
      usuario.bloqueado = false;
      usuario.ativo = true;
    }
  });

  if (String(clientId || "") === String(getClientIdAtual() || billingConfig.clientId || "")) {
    billingConfig.clientId = clientId;
    billingConfig.planSlug = plano.slug;
    billingConfig.activePlan = plano.slug;
    billingConfig.pendingPlan = "";
    billingConfig.pendingStartedAt = "";
    billingConfig.paymentStatus = assinatura.paymentStatus;
    billingConfig.subscriptionStatus = assinatura.subscriptionStatus;
    billingConfig.cancelAtPeriodEnd = false;
    billingConfig.currentPeriodEnd = expiresAt;
    billingConfig.licenseStatus = status;
    billingConfig.licenseBlockLevel = "none";
    billingConfig.paidUntil = expiresAt;
    billingConfig.planExpiresAt = expiresAt;
    billingConfig.monthlyPrice = isPlanoPagoSlug(plano.slug) ? planPrice : 0;
    billingConfig.planPrice = planPrice;
    billingConfig.priceLocked = isPlanoPagoSlug(plano.slug);
    billingConfig.trialStartedAt = assinatura.trialStartedAt;
    billingConfig.trialExpiresAt = assinatura.trialExpiresAt;
    billingConfig.trialConsumedAt = assinatura.trialConsumedAt || billingConfig.trialConsumedAt || "";
    billingConfig.isTrialActive = assinatura.isTrialActive;
    billingConfig.subscriptionId = assinatura.id;
  }

  salvarDados();
  registrarAuditoria("alteração plano", { plano: plano.slug, status, expiresAt, ...detalhes }, clientId);
  return assinatura;
}

async function chamarFuncaoSaas(nome, corpo = {}) {
  if (!syncConfig.supabaseAccessToken) {
    throw new Error("Entre na conta online antes de iniciar o pagamento.");
  }
  syncConfig.supabaseUrl = normalizarUrlSupabase(syncConfig.supabaseUrl || SUPABASE_DEFAULT_URL);
  syncConfig.supabaseAnonKey = syncConfig.supabaseAnonKey || SUPABASE_DEFAULT_ANON_KEY;
  return await requisicaoSupabase(`/functions/v1/${nome}`, {
    method: "POST",
    body: JSON.stringify(corpo)
  });
}

function registrarPagamentoLocalPendente(plano, dados = {}, tipo = "subscription") {
  limparCheckoutsLocaisExpirados({ force: true });
  const clientId = getClientIdAtual() || billingConfig.clientId;
  const assinatura = garantirAssinaturaClienteLocal(clientId);
  const billingVariant = normalizarBillingVariant(dados.billing_variant || dados.billingVariant || getBillingVariantAssinatura(assinatura));
  const precoPadrao = getPrecoBillingVariant(billingVariant);
  const planPrice = Math.max(0, Number(dados.plan_price ?? dados.planPrice ?? dados.amount ?? dados.valor ?? precoPadrao) || precoPadrao);
  const createdAt = new Date().toISOString();
  const expiresAt = new Date(Date.now() + LOCAL_CHECKOUT_PENDING_TTL_MS).toISOString();
  const pagamento = normalizarPagamentoSaas({
    clientId,
    subscriptionId: assinatura.id,
    mercadoPagoSubscriptionId: dados.subscriptionId || assinatura.mercadoPagoSubscriptionId || "",
    preferenceId: dados.preference_id || dados.preferenceId || "",
    externalReference: dados.external_reference || "",
    planSlug: plano.slug,
    billingVariant,
    amount: Number(dados.amount || dados.valor || planPrice),
    status: "checkout_opened",
    paymentMethod: "mercado_pago",
    createdAt
  });
  pagamento.planPrice = planPrice;
  pagamento.checkoutExpiresAt = expiresAt;
  saasPayments.unshift(pagamento);
  saasPayments = saasPayments.slice(0, 500);
  if (dados.subscriptionId) assinatura.mercadoPagoSubscriptionId = String(dados.subscriptionId);
  assinatura.lastCheckoutAt = createdAt;
  assinatura.lastCheckoutPlan = plano.slug;
  assinatura.lastCheckoutExpiresAt = expiresAt;
  assinatura.lastCheckoutPrice = planPrice;
  billingConfig.lastCheckoutAt = createdAt;
  billingConfig.lastCheckoutPlan = plano.slug;
  billingConfig.lastCheckoutExpiresAt = expiresAt;
  billingConfig.lastCheckoutPrice = planPrice;
  try {
    window.sessionStorage?.setItem?.(CHECKOUT_SESSION_STORAGE_KEY, JSON.stringify({
      planSlug: plano.slug,
      billingVariant,
      planPrice,
      preferenceId: pagamento.preferenceId,
      createdAt,
      expiresAt
    }));
  } catch (_) {}
  salvarDados();
  registrarAuditoria("checkout aberto", { tipo, plano: plano.slug, preferenceId: pagamento.preferenceId, subscriptionId: pagamento.mercadoPagoSubscriptionId }, clientId);
  registrarEventoPlanoSeguro("checkout_opened", { plan: plano.slug, type: tipo });
}

async function abrirLinkMercadoPago(slug = "pro") {
  const plano = getPlanoSaas(slug);
  if (plano.slug === "start" && !isStartPlanCommerciallyEnabled()) {
    registrarEventoPlanoSeguro("plan_start_unavailable_clicked", { plan: "start" });
    mostrarToast("O plano Start será liberado em breve. A contratação segura disponível agora é o Pro.", "info", 6500);
    return;
  }
  if (!["start", "pro"].includes(plano.slug)) {
    trocarTela("assinatura");
    return;
  }

  const clientId = getClientIdAtual() || billingConfig.clientId;
  if (!clientId) {
    alert("Crie ou entre na conta antes de escolher um plano.");
    trocarTela("admin");
    return;
  }

  const planEvent = plano.slug === "start" ? "start_plan_checkout_requested" : "plan_checkout_clicked";
  registrarEventoPlanoSeguro(planEvent, { plan: plano.slug });
  if (plano.slug === "pro" && normalizarSlugPlano(billingConfig.activePlan || billingConfig.planSlug || "free") === "start") {
    registrarEventoPlanoSeguro("start_to_pro_upgrade_requested", { from: "start", to: "pro" });
  }
  const confirmou = await solicitarConfirmacaoAcao({
    titulo: `Assinar plano ${plano.slug === "start" ? "Start" : "Pro"}`,
    mensagem: "Você será direcionado ao pagamento seguro do Mercado Pago. Seu plano será ativado automaticamente após a confirmação.",
    confirmar: "Continuar para pagamento"
  });
  if (!confirmou) return;

  registrarAuditoria("tentativa", { tipo: "assinatura", plano: plano.slug }, clientId);
  try {
    const assinatura = garantirAssinaturaClienteLocal(clientId);
    const billingVariant = plano.slug === "start" ? "start_monthly" : "pro_monthly";
    const planPrice = getPrecoBillingVariant(billingVariant);
    const checkoutFunction = plano.slug === "start" ? "mercadopago-create-subscription" : "mercadopago-create-payment";
    const dados = await chamarFuncaoSaas(checkoutFunction, {
      clienteId: clientId,
      plan_id: plano.slug,
      billing_variant: billingVariant,
      plan_price: planPrice,
      amount: planPrice,
      plan: plano.slug,
      planSlug: plano.slug,
      email: getEmailLicencaAtual()
    });
    if (!dados?.init_point) throw new Error("Link de pagamento não retornado.");
    if (plano.slug === "start") registrarEventoPlanoSeguro("start_plan_checkout_created", { plan: "start" });
    registrarPagamentoLocalPendente(plano, dados, "payment");
    window.open(dados.init_point, "_blank");
  } catch (erro) {
    if (plano.slug === "start") registrarEventoPlanoSeguro("start_plan_checkout_failed", { plan: "start", reason: erro?.message || "unknown" });
    registrarDiagnostico("Mercado Pago", "Pagamento não criado", erro.message);
    registrarErroAplicacaoSilencioso("PAYMENT_STATUS_FAILED", erro, "Criar pagamento Mercado Pago", { plano: plano.slug });
    if (billingConfig.mercadoPagoLink) {
      window.open(billingConfig.mercadoPagoLink, "_blank");
      return;
    }
    alert(erro.message || "Não foi possível iniciar o pagamento agora.");
  }
}

async function criarPagamentoUnicoMercadoPago(slug = "pro") {
  const plano = getPlanoSaas(slug);
  if (plano.slug === "start" && !isStartPlanCommerciallyEnabled()) {
    registrarEventoPlanoSeguro("plan_start_unavailable_clicked", { plan: "start", origin: "single-payment" });
    mostrarToast("O plano Start ainda não está disponível para contratação.", "info", 5500);
    return;
  }
  if (!["start", "pro"].includes(plano.slug)) {
    alert("Pagamento disponível para planos pagos.");
    return;
  }

  const clientId = getClientIdAtual() || billingConfig.clientId;
  if (!clientId) {
    alert("Crie ou entre na conta antes de pagar.");
    trocarTela("admin");
    return;
  }

  try {
    const assinatura = garantirAssinaturaClienteLocal(clientId);
    const billingVariant = plano.slug === "start" ? "start_monthly" : "pro_monthly";
    const planPrice = getPrecoBillingVariant(billingVariant);
    const checkoutFunction = plano.slug === "start" ? "mercadopago-create-subscription" : "mercadopago-create-payment";
    const dados = await chamarFuncaoSaas(checkoutFunction, {
      clienteId: clientId,
      plan_id: plano.slug,
      billing_variant: billingVariant,
      plan_price: planPrice,
      amount: planPrice,
      plan: plano.slug,
      planSlug: plano.slug,
      email: getEmailLicencaAtual()
    });
    if (!dados?.init_point) throw new Error("Link de pagamento não retornado.");
    registrarPagamentoLocalPendente(plano, dados, "payment");
    window.open(dados.init_point, "_blank");
  } catch (erro) {
    registrarDiagnostico("Mercado Pago", "Pagamento não criado", erro.message);
    registrarErroAplicacaoSilencioso("PAYMENT_STATUS_FAILED", erro, "Criar pagamento avulso Mercado Pago", { plano: plano.slug });
    alert(erro.message || "Não foi possível iniciar o pagamento agora.");
  }
}

async function cancelarAssinaturaCliente() {
  const clientId = getClientIdAtual() || billingConfig.clientId;
  const assinatura = garantirAssinaturaClienteLocal(clientId);
  const accessState = getPlanAccessState(assinatura, { source: "cancel-renewal" });
  if (accessState.isFree || !accessState.isActive) {
    alert("O plano Free não possui renovação para cancelar.");
    return;
  }
  if (accessState.isCancelingAtPeriodEnd) {
    alert("A renovação já está cancelada. Seu acesso pago continua até o fim do período.");
    return;
  }
  const fimPeriodo = accessState.accessEndsAt || assinatura.currentPeriodEnd || assinatura.planExpiresAt || assinatura.expiresAt || new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString();
  const dataFim = fimPeriodo ? new Date(fimPeriodo).toLocaleDateString("pt-BR") : "o fim do período pago";
  const confirmou = await solicitarConfirmacaoAcao({
    titulo: "Cancelar renovação automática",
    mensagem: `Deseja cancelar a renovação automática? Seu plano ${getPlanoSaas(accessState.effectivePlan).name} continuará ativo até ${dataFim}. Depois disso, sua conta voltará ao plano Free.`,
    confirmar: "Cancelar renovação",
    perigo: true
  });
  if (!confirmou) return;
  registrarEventoPlanoSeguro("subscription_cancel_requested", { plan: accessState.effectivePlan, accessEndsAt: fimPeriodo });

  try {
    if (syncConfig.supabaseAccessToken && assinatura.mercadoPagoSubscriptionId) {
      await chamarFuncaoSaas("mercadopago-cancel-subscription", {
        clienteId: clientId,
        subscriptionId: assinatura.mercadoPagoSubscriptionId
      });
    }
  } catch (erro) {
    registrarDiagnostico("Mercado Pago", "Cancelamento online não confirmado", erro.message);
    alert("Não foi possível confirmar o cancelamento automático. Vamos manter a solicitação local e o suporte pode conferir a cobrança.");
  }

  const agora = new Date().toISOString();
  assinatura.cancelAtPeriodEnd = true;
  assinatura.subscriptionStatus = "canceling";
  assinatura.status = "active";
  assinatura.statusAssinatura = "canceling";
  assinatura.paymentStatus = "none";
  assinatura.pendingPlan = "";
  assinatura.pendingStartedAt = "";
  assinatura.currentPeriodEnd = fimPeriodo || assinatura.currentPeriodEnd || "";
  assinatura.expiresAt = fimPeriodo || assinatura.expiresAt || "";
  assinatura.planExpiresAt = fimPeriodo || assinatura.planExpiresAt || "";
  assinatura.updatedAt = agora;
  const cliente = getClienteSaasPorId(clientId);
  if (cliente) {
    cliente.cancelAtPeriodEnd = true;
    cliente.subscriptionStatus = "canceling";
    cliente.statusAssinatura = "canceling";
    cliente.pendingPlan = "";
    cliente.pendingStartedAt = "";
    cliente.paymentStatus = "none";
    cliente.currentPeriodEnd = fimPeriodo || cliente.currentPeriodEnd || "";
    cliente.planExpiresAt = fimPeriodo || cliente.planExpiresAt || "";
    cliente.updatedAt = agora;
  }
  if (String(clientId || "") === String(getClientIdAtual() || billingConfig.clientId || "")) {
    billingConfig.cancelAtPeriodEnd = true;
    billingConfig.subscriptionStatus = "canceling";
    billingConfig.licenseStatus = "active";
    billingConfig.paymentStatus = "none";
    billingConfig.pendingPlan = "";
    billingConfig.pendingStartedAt = "";
    billingConfig.currentPeriodEnd = fimPeriodo || billingConfig.currentPeriodEnd || "";
    billingConfig.planExpiresAt = fimPeriodo || billingConfig.planExpiresAt || "";
    billingConfig.paidUntil = fimPeriodo || billingConfig.paidUntil || "";
  }
  salvarDados();
  registrarAuditoria("cancelamento renovacao", { plano: accessState.effectivePlan, accessEndsAt: fimPeriodo, origem: "cliente" }, clientId);
  registrarEventoPlanoSeguro("subscription_cancel_at_period_end", { plan: accessState.effectivePlan, accessEndsAt: fimPeriodo });
  alert(`Renovação cancelada. O acesso pago continua liberado até ${dataFim}.`);
  renderApp();
}

async function reativarRenovacaoAssinaturaCliente() {
  const clientId = getClientIdAtual() || billingConfig.clientId;
  const assinatura = garantirAssinaturaClienteLocal(clientId);
  const accessState = getPlanAccessState(assinatura, { source: "reactivate-renewal" });
  if (!accessState.isCancelingAtPeriodEnd) {
    alert("Não há cancelamento de renovação agendado para reativar.");
    return;
  }
  const confirmou = await solicitarConfirmacaoAcao({
    titulo: "Reativar renovação automática",
    mensagem: "Deseja reativar a renovação automática do seu plano Pro?",
    confirmar: "Reativar renovação"
  });
  if (!confirmou) return;
  assinatura.cancelAtPeriodEnd = false;
  assinatura.subscriptionStatus = "active";
  assinatura.status = "active";
  assinatura.statusAssinatura = "active";
  assinatura.updatedAt = new Date().toISOString();
  const cliente = getClienteSaasPorId(clientId);
  if (cliente) {
    cliente.cancelAtPeriodEnd = false;
    cliente.subscriptionStatus = "active";
    cliente.statusAssinatura = "active";
    cliente.updatedAt = new Date().toISOString();
  }
  if (String(clientId || "") === String(getClientIdAtual() || billingConfig.clientId || "")) {
    billingConfig.cancelAtPeriodEnd = false;
    billingConfig.subscriptionStatus = "active";
    billingConfig.licenseStatus = "active";
  }
  salvarDados();
  registrarAuditoria("reativacao renovacao", { plano: accessState.effectivePlan }, clientId);
  registrarEventoPlanoSeguro("subscription_reactivated", { plan: accessState.effectivePlan });
  alert("Renovação reativada. Sua assinatura continua ativa normalmente.");
  renderApp();
}

function falarComSuporteAssinatura() {
  const texto = `Olá, preciso de suporte na assinatura do ${SYSTEM_NAME}. Cliente: ${getClienteCodigoAtual() || getEmailLicencaAtual() || "não identificado"}`;
  if (billingConfig.supportUrl) {
    window.open(billingConfig.supportUrl, "_blank");
    return;
  }
  const whats = normalizarTelefoneWhatsapp(appConfig.whatsappNumber || "");
  if (whats) {
    window.open(`https://wa.me/${whats}?text=${encodeURIComponent(texto)}`, "_blank");
    return;
  }
  window.open(`mailto:${SUPPORT_EMAIL}?subject=Suporte Simplifica 3D&body=${encodeURIComponent(texto)}`, "_blank");
}

